+    fn autograph(&self) -> Option<&str> {
+        self.option("autograph").filter(|value| !value.is_empty())
+    }
+
+    fn epub_version(&self) -> u32 {
+        self.option("epub.version")
+            .and_then(|value| value.parse::<u32>().ok())
+            .unwrap_or(2)
+    }
+
+    fn get_bool(&self, key: &str, default: bool) -> bool {
+        self.option(key)
+            .map(parse_bool)
+            .unwrap_or(default)
+    }
+
+    fn output_path(&self, format: OutputFormat) -> Option<String> {
+        let key = match format {
+            OutputFormat::Html => "output.html",
+            OutputFormat::HtmlDir => "output.html.dir",
+            OutputFormat::Epub => "output.epub",
+            OutputFormat::Pdf => "output.pdf",
+            OutputFormat::Tex => "output.tex",
+            OutputFormat::Odt => "output.odt",
+        };
+        self.option(key).map(str::to_owned)
+    }
+
+    fn output_list(&self) -> Vec<String> {
+        let Some(raw) = self.option("output") else {
+            return Vec::new();
+        };
+        let trimmed = raw.trim();
+        let inner = trimmed
+            .strip_prefix('[')
+            .and_then(|value| value.strip_suffix(']'))
+            .unwrap_or(trimmed);
+        inner
+            .split(|c: char| c == ',' || c.is_whitespace())
+            .filter(|part| !part.is_empty())
+            .map(|part| part.to_owned())
+            .collect()
+    }
+
+    fn default_output_name(&self, format: OutputFormat) -> String {
+        let stem = self
+            .source_path
+            .file_stem()
+            .and_then(|value| value.to_str())
+            .filter(|value| !value.is_empty())
+            .unwrap_or("book");
+        match format {
+            OutputFormat::Html => format!("{stem}.html"),
+            OutputFormat::Epub => format!("{stem}.epub"),
+            OutputFormat::Pdf => format!("{stem}.pdf"),
+            OutputFormat::Tex => format!("{stem}.tex"),
+            OutputFormat::HtmlDir => stem.to_owned(),
+            OutputFormat::Odt => format!("{stem}.odt"),
+        }
+    }
+
+    fn tex_class(&self) -> &str {
+        self.option("tex.class")
+            .unwrap_or(if self.single_mode { "article" } else { "book" })
+    }
