+fn emit_banner(ui: UiMode) -> Result<(), String> {
+    if ui != UiMode::Quiet {
+        let mut stderr = io::stderr().lock();
+        writeln!(stderr, "{BANNER}").map_err(|error| error.to_string())?;
+    }
+    Ok(())
+}
+
+fn emit_plain_error<S: AsRef<str>>(ui: UiMode, message: S) -> Result<(), String> {
+    let mut stderr = io::stderr().lock();
+    match ui {
+        UiMode::Quiet => {
+            writeln!(stderr, "ERROR {}", message.as_ref()).map_err(|error| error.to_string())?;
+        }
+        _ => {
+            writeln!(stderr, "ERROR {}", message.as_ref()).map_err(|error| error.to_string())?;
+        }
+    }
+    Ok(())
+}
+
+fn emit_missing_book(ui: UiMode) -> Result<(), String> {
+    let mut stderr = io::stderr().lock();
+    writeln!(stderr, "ERROR You must pass the name of a book configuration file.")
+        .map_err(|error| error.to_string())?;
+    if ui != UiMode::Quiet {
+        writeln!(stderr, "{HELP_HINT}").map_err(|error| error.to_string())?;
+    } else {
+        writeln!(stderr, "{HELP_HINT}").map_err(|error| error.to_string())?;
+    }
+    Ok(())
+}
+
+fn emit_generation_issues(ui: UiMode, issues: &[Issue]) -> Result<(), String> {
+    if issues.is_empty() {
+        return Ok(());
+    }
+    let mut stderr = io::stderr().lock();
+    match ui {
+        UiMode::Default => {
+            if issues.iter().any(|issue| issue.severity == Severity::Warn) {
+                writeln!(
+                    stderr,
+                    "WARNING Crowbook exited successfully, but the following errors occurred:"
+                )
+                .map_err(|error| error.to_string())?;
+                for issue in issues {
+                    let label = match issue.severity {
+                        Severity::Warn => "WARNING",
+                        Severity::Error => "ERROR",
+                    };
+                    writeln!(stderr, "{label} {}", issue.short).map_err(|error| error.to_string())?;
+                }
+            } else {
+                for issue in issues {
+                    if let Some(detailed) = &issue.detailed {
+                        writeln!(stderr, "ERROR {detailed}").map_err(|error| error.to_string())?;
+                    } else {
+                        writeln!(stderr, "ERROR {}", issue.short)
+                            .map_err(|error| error.to_string())?;
+                    }
+                }
+            }
+        }
+        UiMode::Quiet | UiMode::NoFancy | UiMode::Verbose => {
+            for issue in issues {
+                if issue.severity == Severity::Warn && ui == UiMode::Quiet {
+                    continue;
+                }
+                let label = match issue.severity {
+                    Severity::Warn => "[WARN]",
+                    Severity::Error => "[ERROR]",
+                };
+                if let Some(detailed) = &issue.detailed {
+                    writeln!(stderr, "{label} {detailed}").map_err(|error| error.to_string())?;
+                } else {
+                    writeln!(stderr, "{label} {}", issue.short)
+                        .map_err(|error| error.to_string())?;
+                }
+            }
+        }
+    }
+    Ok(())
+}
