+fn render_json_ld(book: &Book) -> String {
+    format!(
+        "<script type = 'application/ld+json'>\n{{\n    \"@context\": \"http://schema.org/\",\n    \"@type\": \"Book\",\n    \"author\": \"{}\",\n    \"name\": \"{}\",\n    \n    \n    \n    \n    \n    \"inLanguage\": \"{}\"\n}}\n</script>",
+        escape_html(book.author()),
+        escape_html(book.title()),
+        book.lang()
+    )
+}
