+fn write_epub(book: &Book, chapters: &[RenderedChapter], destination: Destination<'_>) -> Result<(), String> {
+    let mut buffer = Vec::new();
+    {
+        let cursor = io::Cursor::new(&mut buffer);
+        let mut zip = ZipWriter::new(cursor);
+        let stored: FileOptions<'_, ()> =
+            FileOptions::default().compression_method(CompressionMethod::Stored);
+        let deflated: FileOptions<'_, ()> =
+            FileOptions::default().compression_method(CompressionMethod::Deflated);
+
+        zip.start_file("mimetype", stored)
+            .map_err(|error| error.to_string())?;
+        zip.write_all(b"application/epub+zip")
+            .map_err(|error| error.to_string())?;
+
+        write_zip_file(
+            &mut zip,
+            "META-INF/container.xml",
+            render_container_xml().as_bytes(),
+            deflated,
+        )?;
+        write_zip_file(
+            &mut zip,
+            "META-INF/com.apple.ibooks.display-options.xml",
+            render_ibooks_display_options().as_bytes(),
+            deflated,
+        )?;
+        write_zip_file(
+            &mut zip,
+            "OEBPS/title_page.xhtml",
+            render_epub_title_page(book).as_bytes(),
+            deflated,
+        )?;
+        for (index, chapter) in chapters.iter().enumerate() {
+            let path = format!("OEBPS/chapter_{index:03}.xhtml");
+            write_zip_file(
+                &mut zip,
+                &path,
+                render_epub_chapter(book, chapter).as_bytes(),
+                deflated,
+            )?;
+        }
+        write_zip_file(
+            &mut zip,
+            "OEBPS/stylesheet.css",
+            render_epub_css(book.lang()).as_bytes(),
+            deflated,
+        )?;
+        write_zip_file(
+            &mut zip,
+            "OEBPS/content.opf",
+            render_opf(book, chapters).as_bytes(),
+            deflated,
+        )?;
+        write_zip_file(
+            &mut zip,
+            "OEBPS/toc.ncx",
+            render_toc_ncx(book, chapters).as_bytes(),
+            deflated,
+        )?;
+        write_zip_file(
+            &mut zip,
+            "OEBPS/nav.xhtml",
+            render_nav_xhtml(book, chapters).as_bytes(),
+            deflated,
+        )?;
+        zip.finish().map_err(|error| error.to_string())?;
+    }
+
+    match destination {
+        Destination::Stdout => {
+            let mut stdout = io::stdout().lock();
+            stdout.write_all(&buffer).map_err(|error| error.to_string())?;
+        }
+        Destination::Path(path) => {
+            if let Some(parent) = Path::new(path).parent() {
+                if !parent.as_os_str().is_empty() {
+                    fs::create_dir_all(parent).map_err(|error| error.to_string())?;
+                }
+            }
+            fs::write(path, buffer).map_err(|error| error.to_string())?;
+        }
+    }
+    Ok(())
+}
+
+fn write_zip_file<W: Write + io::Seek>(
+    zip: &mut ZipWriter<W>,
+    name: &str,
+    bytes: &[u8],
+    options: FileOptions<'_, ()>,
+) -> Result<(), String> {
+    zip.start_file(name, options)
+        .map_err(|error| error.to_string())?;
+    zip.write_all(bytes).map_err(|error| error.to_string())?;
+    Ok(())
+}
