+fn render_epub_title_page(book: &Book) -> String {
+    let lang = book.lang();
+    let title = escape_html(book.title());
+    let author = escape_html(book.author());
+    let subtitle = book.subtitle().map(escape_html);
+    let autograph = book.autograph().map(escape_html);
+
+    let mut out = String::new();
+    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
+    out.push_str("<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n");
+    writeln!(out, "<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"{lang}\">").ok();
+    out.push_str("<head>\n");
+    out.push_str("  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n");
+    out.push_str("  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n");
+    out.push_str("  <meta name=\"generator\" content=\"crowbook\" />\n");
+    writeln!(out, "  <title>{title}</title>").ok();
+    out.push_str("  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n");
+    out.push_str("</head>\n");
+    out.push_str("<body>\n");
+    writeln!(out, "  <h2 class=\"author\">{author}</h2>").ok();
+    writeln!(out, "  <h1 class=\"title\">{title}</h1>").ok();
+    if let Some(subtitle) = subtitle {
+        writeln!(out, "  <h2 class = \"subtitle\">{subtitle}</h2>").ok();
+    } else {
+        out.push_str("  \n");
+    }
+    if let Some(autograph) = autograph {
+        writeln!(out, "  <div id = \"autograph\">{autograph}</div>").ok();
+    } else {
+        out.push_str("  \n");
+    }
+    out.push_str("</body>\n");
+    out.push_str("</html>\n");
+    out
+}
