+fn render_toc_ncx(book: &Book, chapters: &[RenderedChapter]) -> String {
+    let mut out = String::new();
+    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
+    out.push_str("<ncx version=\"2005-1\" xmlns=\"http://www.daisy.org/z3986/2005/ncx/\">\n");
+    out.push_str("  <head>\n");
+    out.push_str("    <meta name=\"dtb:depth\" content=\"1\" />\n");
+    out.push_str("    <meta name=\"dtb:totalPageCount\" content=\"0\" />\n");
+    out.push_str("    <meta name=\"dtb:maxPageNumber\" content=\"0\" />\n");
+    out.push_str("  </head>\n");
+    out.push_str("  <docTitle>\n");
+    writeln!(out, "    <text>{}</text>", toc_title(book.lang())).ok();
+    out.push_str("  </docTitle>\n");
+    out.push_str("  <navMap>\n");
+    out.push_str("    <navPoint playOrder=\"1\" id=\"navPoint-1\">\n");
+    out.push_str("      <navLabel>\n");
+    writeln!(out, "       <text>{}</text>", title_page_label(book.lang())).ok();
+    out.push_str("      </navLabel>\n");
+    out.push_str("      <content src=\"title_page.xhtml\"/>\n");
+    out.push_str("    </navPoint>\n");
+    for (index, chapter) in chapters.iter().enumerate() {
