+        writeln!(out, "       <text>{}</text>", escape_html(&chapter.title_label)).ok();
+        out.push_str("      </navLabel>\n");
+        writeln!(out, "      <content src=\"chapter_{index:03}.xhtml\"/>").ok();
+        out.push_str("    </navPoint>\n");
+    }
+    out.push_str("  </navMap>\n");
+    out.push_str("</ncx>\n");
+    out
+}
