+fn render_opf(book: &Book, chapters: &[RenderedChapter]) -> String {
+    let uuid = format!("urn:uuid:{}", Uuid::new_v4());
+    let version = book.epub_version();
+    let lang = book.lang();
+    let mut out = String::new();
+    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
+    if version == 3 {
+        out.push_str("<package version=\"3.0\" xmlns=\"http://www.idpf.org/2007/opf\" unique-identifier=\"epub-id-1\">\n");
+    } else {
+        out.push_str("<package version=\"2.0\" xmlns=\"http://www.idpf.org/2007/opf\" unique-identifier=\"epub-id-1\">\n");
+    }
+    out.push_str("  <metadata xmlns:dc=\"http://purl.org/dc/elements/1.1/\"\n");
+    out.push_str("            xmlns:opf=\"http://www.idpf.org/2007/opf\">\n");
+    writeln!(out, "    <dc:identifier id=\"epub-id-1\">{uuid}</dc:identifier>").ok();
+    writeln!(out, "    <dc:title>{}</dc:title>", escape_html(book.title())).ok();
+    out.push_str("    \n");
+    out.push_str("    \n");
+    if version == 3 {
+        writeln!(out, "    <dc:language id=\"epub-creator-0\">{lang}</dc:language>").ok();
+    } else {
+        writeln!(out, "    <dc:language>{lang}</dc:language>").ok();
+    }
+    out.push_str("    \n");
+    out.push_str("    \n");
+    out.push_str("    \n");
+    if version == 3 {
+        writeln!(
+            out,
+            "    <dc:creator id=\"epub-creator-0\">{}</dc:creator>",
+            escape_html(book.author())
+        )
+        .ok();
+        out.push_str("    <meta refines=\"#epub-creator-0\" property=\"role\" scheme=\"marc:relators\">aut</meta>\n");
+    } else {
+        writeln!(
+            out,
+            "    <dc:creator opf:role=\"aut\">{}</dc:creator>",
+            escape_html(book.author())
+        )
+        .ok();
+    }
+    out.push_str("    \n");
+    if version == 3 {
+        writeln!(
+            out,
+            "    <meta property=\"dcterms:modified\">{}</meta>",
+            Utc::now().format("%Y-%m-%dT%H:%M:%SZ")
+        )
+        .ok();
+        out.push_str("\n");
+    } else {
+        out.push_str("    \n");
+    }
+    out.push_str("  </metadata>\n");
+    out.push_str("  <manifest>\n");
+    out.push_str("    <item id=\"ncx\" href=\"toc.ncx\" media-type=\"application/x-dtbncx+xml\"/>\n");
+    if version == 3 {
+        out.push_str(
+            "    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\" properties=\"nav\"/>\n",
+        );
+    } else {
+        out.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\"/>\n");
+    }
+    out.push_str("    <item media-type=\"application/xhtml+xml\" id=\"id_title_page.xhtml\" href=\"title_page.xhtml\"/>\n");
+    for (index, _) in chapters.iter().enumerate() {
+        writeln!(
+            out,
+            "    <item media-type=\"application/xhtml+xml\" id=\"id_chapter_{index:03}.xhtml\" href=\"chapter_{index:03}.xhtml\"/>"
+        )
+        .ok();
+    }
+    out.push_str("    <item media-type=\"text/css\" id=\"id_stylesheet.css\" href=\"stylesheet.css\"/>\n");
+    out.push_str("  </manifest>\n");
+    if version == 3 {
+        out.push_str("  <spine toc=\"ncx\" page-progression-direction=\"ltr\">\n");
+    } else {
+        out.push_str("  <spine toc=\"ncx\">\n");
+    }
+    out.push_str("    <itemref idref=\"id_title_page.xhtml\"/>\n");
+    for (index, _) in chapters.iter().enumerate() {
+        writeln!(out, "    <itemref idref=\"id_chapter_{index:03}.xhtml\"/>").ok();
+    }
+    out.push_str("  </spine>\n");
+    out.push_str("  <guide>\n");
+    writeln!(
+        out,
+        "    <reference type=\"toc\" title=\"{}\" href=\"nav.xhtml\"/>",
+        toc_title(book.lang())
+    )
+    .ok();
+    writeln!(
+        out,
+        "    <reference type=\"title-page\" title=\"{}\" href=\"title_page.xhtml\"/>",
+        title_page_label(book.lang())
+    )
+    .ok();
+    for (index, chapter) in chapters.iter().enumerate() {
+        writeln!(
+            out,
+            "    <reference type=\"text\" title=\"{}\" href=\"chapter_{index:03}.xhtml\"/>",
+            escape_html(&chapter.title_label)
+        )
+        .ok();
+    }
+    out.push_str("  </guide>\n");
+    out.push_str("</package>\n");
+    out
+}
