+fn write_html_dir(book: &Book, chapters: &[RenderedChapter], path: &str) -> Result<(), String> {
+    let directory = Path::new(path);
+    if directory.exists() {
+        fs::remove_dir_all(directory).map_err(|error| error.to_string())?;
+    }
+    fs::create_dir_all(directory).map_err(|error| error.to_string())?;
+    fs::write(directory.join("stylesheet.css"), render_html_css(book.lang()))
+        .map_err(|error| error.to_string())?;
+    fs::write(
+        directory.join("print.css"),
+        include_str!("../observed/templates/html.css.print"),
+    )
+    .map_err(|error| error.to_string())?;
+    for (index, chapter) in chapters.iter().enumerate() {
+        let file_name = format!("chapter_{index:03}.html");
+        fs::write(directory.join(file_name), render_html_dir_chapter(book, chapters, chapter, index))
+            .map_err(|error| error.to_string())?;
+    }
+    Ok(())
+}
