fn render_tex(book: &Book, chapters: &[RenderedChapter]) -> String {
    let class = book.tex_class();
    let lang = match book.lang() {
        "fr" => "french",
        _ => "english",
    };
    let title = escape_tex(book.title());
    let author = escape_tex(book.author());
    let description = escape_tex(book.option("description").unwrap_or(""));

    let mut out = String::new();
    writeln!(out, "\\documentclass{{{class}}}").ok();
    out.push_str("\n%% Package inclusion\n\n");
    out.push_str("% Unicode support if xelatex is used\n");
    out.push_str("\\usepackage{fontspec}\n");
    out.push_str("\\usepackage{xunicode}\n\n\n");
    writeln!(out, "\\usepackage[{lang}]{{babel}} % Language support").ok();
    out.push_str("\\usepackage{fancyhdr} % Headers\n");
    out.push_str("\\usepackage{enumitem}\n\n");
    out.push_str("% Allows hyphenatations in \\texttt\n");
    out.push_str("\\usepackage[htt]{hyphenat}\n\n\n\n");
    out.push_str("% Set hyperlinks and metadata\n");
    out.push_str("\\usepackage[colorlinks=true,breaklinks=true,hypertexnames=false]{hyperref}\n");
    writeln!(out, "\\hypersetup{{pdfauthor={{{author}}},").ok();
    writeln!(out, "  pdftitle={{{title}}},").ok();
    writeln!(out, "  pdfsubject={{{description}}}").ok();
    out.push_str("}\n\n\n\n\n\n\n");
    writeln!(
        out,
        "% Included if the stdpage option if set to false\n\\usepackage[{},{},\n  left={},right={}]{{geometry}} % Set dimensions/margins of the page",
        book.tex_paper_size(),
        format!(
            " top={}, bottom={}",
            book.tex_margin_top(),
            book.tex_margin_bottom()
        ),
        book.tex_margin_left(),
        book.tex_margin_right()
    )
    .ok();
    out.push_str("\n\n\n\n\n\n");
    out.push_str("\\makeatletter\n");
    out.push_str("\\date{}\n\n");
    if class == "book" {
        out.push_str("  \n% Redefine the \\maketitle command, only for book class (not used if stdpage option is set to true)\n");
        out.push_str("\\renewcommand{\\maketitle}{\n  \n\n  % First page with only the title\n  \\thispagestyle{empty}\n  \\vspace*{\\stretch{1}}\n\n  \\begin{center}\n    {\\Huge \\@title   \\\\[5mm]}\n  \\end{center}\n  \\vspace*{\\stretch{2}}\n\n  \\newpage\n  % Empty left page\n  \\thispagestyle{empty}\n  \\cleardoublepage\n\n  % Main title page, with author, title, subtitle, date\n  \\begin{center}\n    \\thispagestyle{empty}\n    \\vspace*{\\baselineskip}\n    \\rule{\\textwidth}{1.6pt}\\vspace*{-\\baselineskip}\\vspace*{2pt}\n    \\rule{\\textwidth}{0.4pt}\\\\[\\baselineskip]\n\n    {\\Huge\\scshape \\@title   \\\\[5mm]}\n    {\\Large }\n\n    \\rule{\\textwidth}{0.4pt}\\vspace*{-\\baselineskip}\\vspace{3.2pt}\n    \\rule{\\textwidth}{1.6pt}\\\\[\\baselineskip]\n\n    \\vspace*{4\\baselineskip}\n\n    {\\Large \\@author}\n      \n    \\vfill\n      \n  \\end{center}\n\n  \\pagebreak\n  \\newpage\n  % Copyright page with author, version, and license\n  \\thispagestyle{empty}\n  \\null\\vfill\n  \\noindent\n  \\begin{center}\n    {\\emph{\\@title}, © \\@author.\\\\[5mm]}\n    \n  \\end{center}\n  \\pagebreak\n  \\newpage\n}\n  \n\n");
    }
    out.push_str("% Redefine headers\n");
    out.push_str("\\pagestyle{fancy}\n");
    out.push_str("\\fancyhead{}\n");
    out.push_str("\\fancyhead[CO,CE]{\\thepage}\n");
    out.push_str("\\fancyfoot{}\n\n\n\n\n");
    out.push_str("\\makeatother\n\n");
    writeln!(out, "\\title{{{title}}}").ok();
    writeln!(out, "\\author{{{author}}}").ok();
    out.push_str("\n\\begin{document}\n\n");
    out.push_str("% Redefine chapter and part names if they needs to be\n");
    out.push_str("% Needs to be after \\begin{document} because babel\n\n\n\n\n\n");
    out.push_str("\\maketitle\n\n\n\n\n");
    for chapter in chapters {
        writeln!(out, "{}", chapter.tex_content).ok();
        out.push('\n');
    }
    out.push_str("\\end{document}\n");
    out
}

fn command_missing(command: &str) -> bool {
    let path_var = std::env::var_os("PATH");
    let Some(path_var) = path_var else {
        return true;
    };
    std::env::split_paths(&path_var).all(|directory| !directory.join(command).exists())
}

fn chapter_word(lang: &str) -> &'static str {
    match lang {
        "fr" => "Chapitre",
        _ => "Chapter",
    }
}

fn toc_title(lang: &str) -> &'static str {
    match lang {
        "fr" => "Table des matières",
        _ => "Table of contents",
    }
}

fn title_page_label(lang: &str) -> &'static str {
    match lang {
        "fr" => "Titre",
        _ => "Title",
    }
}

