use chrono::Utc;
use clap::{Parser, ValueEnum};
use regex::Regex;
use std::borrow::Cow;
use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use uuid::Uuid;
use zip::write::{FileOptions, ZipWriter};
use zip::CompressionMethod;

const BANNER: &str = "CROWBOOK 0.17.0";
const HELP_HINT: &str = "For more information try --help.";
const HTML_DIR_ERROR_DETAIL: &str = "Error compiling template: render error\n\n  --> <anonymous>:8:7\n   |\n 8 |     {{favicon}}\n   |       ^^^^^^^\n   |\n   = reason: not found in this scope";
const PDF_ERROR: &str = "Error during temporary files editing: failed to run command 'xelatex'";
const EPUB_ZIP_WARNING: &str = "Could not run zip command, falling back to zip library";

#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
enum OutputFormat {
    Epub,
    Pdf,
    Html,
    Tex,
    Odt,
    #[clap(name = "html.dir")]
    HtmlDir,
}

impl OutputFormat {
    fn key(self) -> &'static str {
        match self {
            Self::Epub => "epub",
            Self::Pdf => "pdf",
            Self::Html => "html",
            Self::Tex => "tex",
            Self::Odt => "odt",
            Self::HtmlDir => "html.dir",
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum UiMode {
    Default,
    Quiet,
    NoFancy,
    Verbose,
}

#[derive(Parser, Debug)]
#[clap(
    name = "crowbook",
    author = "Élisabeth Henry <liz.henry@ouvaton.org>",
    version = "0.17.0",
    about = "Render a Markdown book in EPUB, PDF or HTML.",
    override_usage = "executable [OPTIONS] [BOOK]",
    disable_help_subcommand = true
)]
struct Cli {
    #[clap(short = 'f', long = "force-emoji")]
    force_emoji: bool,
    #[clap(short = 's', long = "single")]
    single: bool,
    #[clap(short = 'n', long = "no-fancy")]
    no_fancy: bool,
    #[clap(short = 'v', long = "verbose")]
    verbose: bool,
    #[clap(short = 'a', long = "autograph")]
    autograph: bool,
    #[clap(short = 'q', long = "quiet")]
    quiet: bool,
    #[clap(short = 'c', long = "create", value_name = "files", multiple_values = true)]
    create: Option<Vec<String>>,
    #[clap(short = 'o', long = "output", value_name = "output", requires = "to")]
    output: Option<String>,
    #[clap(short = 't', long = "to", value_name = "to")]
    to: Option<OutputFormat>,
    #[clap(long = "set", value_name = "set", min_values = 2, multiple_values = true)]
    set: Vec<String>,
    #[clap(short = 'l', long = "list-options")]
    list_options: bool,
    #[clap(short = 'L', long = "lang", value_name = "lang")]
    runtime_lang: Option<String>,
    #[clap(long = "print-template", value_name = "print-template")]
    print_template: Option<String>,
    #[clap(short = 'S', long = "stats")]
    stats: bool,
    #[clap(value_name = "BOOK")]
    book: Option<String>,
}

#[derive(Clone, Debug)]
struct ChapterSource {
    original: String,
    resolved: PathBuf,
    line_number: Option<usize>,
    inline_content: Option<String>,
}

#[derive(Clone, Debug)]
struct Book {
    source_arg: String,
    source_path: PathBuf,
    source_dir: PathBuf,
    single_mode: bool,
    options: BTreeMap<String, String>,
    chapters: Vec<ChapterSource>,
}

impl Book {
    fn option(&self, key: &str) -> Option<&str> {
        self.options.get(key).map(String::as_str)
    }

    fn lang(&self) -> &str {
        self.option("lang").unwrap_or("en")
    }

    fn title(&self) -> &str {
        self.option("title").unwrap_or("")
    }

    fn author(&self) -> &str {
        self.option("author").unwrap_or("")
    }

    fn subtitle(&self) -> Option<&str> {
        self.option("subtitle").filter(|value| !value.is_empty())
    }

    fn autograph(&self) -> Option<&str> {
        self.option("autograph").filter(|value| !value.is_empty())
    }

    fn epub_version(&self) -> u32 {
        self.option("epub.version")
            .and_then(|value| value.parse::<u32>().ok())
            .unwrap_or(2)
    }

    fn get_bool(&self, key: &str, default: bool) -> bool {
        self.option(key)
            .map(parse_bool)
            .unwrap_or(default)
    }

    fn output_path(&self, format: OutputFormat) -> Option<String> {
        let key = match format {
            OutputFormat::Html => "output.html",
            OutputFormat::HtmlDir => "output.html.dir",
            OutputFormat::Epub => "output.epub",
            OutputFormat::Pdf => "output.pdf",
            OutputFormat::Tex => "output.tex",
            OutputFormat::Odt => "output.odt",
        };
        self.option(key).map(str::to_owned)
    }

    fn output_list(&self) -> Vec<String> {
        let Some(raw) = self.option("output") else {
            return Vec::new();
        };
        let trimmed = raw.trim();
        let inner = trimmed
            .strip_prefix('[')
            .and_then(|value| value.strip_suffix(']'))
            .unwrap_or(trimmed);
        inner
            .split(|c: char| c == ',' || c.is_whitespace())
            .filter(|part| !part.is_empty())
            .map(|part| part.to_owned())
            .collect()
    }

    fn default_output_name(&self, format: OutputFormat) -> String {
        let stem = self
            .source_path
            .file_stem()
            .and_then(|value| value.to_str())
            .filter(|value| !value.is_empty())
            .unwrap_or("book");
        match format {
            OutputFormat::Html => format!("{stem}.html"),
            OutputFormat::Epub => format!("{stem}.epub"),
            OutputFormat::Pdf => format!("{stem}.pdf"),
            OutputFormat::Tex => format!("{stem}.tex"),
            OutputFormat::HtmlDir => stem.to_owned(),
            OutputFormat::Odt => format!("{stem}.odt"),
        }
    }

    fn tex_class(&self) -> &str {
        self.option("tex.class")
            .unwrap_or(if self.single_mode { "article" } else { "book" })
    }

    fn tex_paper_size(&self) -> &str {
        self.option("tex.paper.size").unwrap_or("a5paper")
    }

    fn tex_margin_top(&self) -> &str {
        self.option("tex.margin.top").unwrap_or("2cm")
    }

    fn tex_margin_bottom(&self) -> &str {
        self.option("tex.margin.bottom").unwrap_or("1.5cm")
    }

    fn tex_margin_left(&self) -> Cow<'_, str> {
        if let Some(value) = self.option("tex.margin.left") {
            return Cow::Borrowed(value);
        }
        if self.tex_class() == "book" {
            Cow::Borrowed("2.5cm")
        } else {
            Cow::Borrowed("2cm")
        }
    }

    fn tex_margin_right(&self) -> Cow<'_, str> {
        if let Some(value) = self.option("tex.margin.right") {
            return Cow::Borrowed(value);
        }
        if self.tex_class() == "book" {
            Cow::Borrowed("1.5cm")
        } else {
            Cow::Borrowed("2cm")
        }
    }
}

#[derive(Clone, Debug)]
struct RenderedChapter {
    title: String,
    title_label: String,
    html_content: String,
    tex_content: String,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Destination<'a> {
    Stdout,
    Path(&'a str),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Target<'a> {
    format: OutputFormat,
    destination: Destination<'a>,
    explicit: bool,
}

#[derive(Clone, Debug)]
struct Issue {
    severity: Severity,
    short: String,
    detailed: Option<String>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Severity {
    Warn,
    Error,
}

fn main() {
    let cli = Cli::parse();
    if let Err(error) = run(cli) {
        eprintln!("{error}");
        std::process::exit(1);
    }
}

fn run(cli: Cli) -> Result<(), String> {
    let ui = if cli.quiet {
        UiMode::Quiet
    } else if cli.verbose {
        UiMode::Verbose
    } else if cli.no_fancy {
        UiMode::NoFancy
    } else {
        UiMode::Default
    };

    if cli.list_options {
        emit_banner(ui)?;
        print!("{}", include_str!("../observed/misc/list-options.txt"));
        return Ok(());
    }

    if let Some(name) = cli.print_template.as_deref() {
        emit_banner(ui)?;
        if let Some(content) = template_content(name) {
            print!("{content}");
        } else {
            emit_plain_error(ui, format!("{name} is not a valid template name"))?;
        }
        return Ok(());
    }

    if let Some(files) = cli.create.as_ref() {
        emit_banner(ui)?;
        let mut out = String::new();
        out.push_str("\"author: Your name\"\n");
        out.push_str("\"title: Your title\"\n");
        out.push_str("\"lang: en\"\n\n");
        out.push_str("\"## Output formats\"\n\n");
        out.push_str("\"# Uncomment and fill to generate files\"\n");
        out.push_str("\"# output.html: some_file.html\"\n");
        out.push_str("\"# output.epub: some_file.epub\"\n");
        out.push_str("\"# output.pdf: some_file.pdf\"\n\n");
        out.push_str("\"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file's name\"\n");
        out.push_str("\"# output: [pdf, epub, html]\"\n\n");
        out.push_str("\"# Uncomment and fill to set cover image (for EPUB)\"\n");
        out.push_str("\"# cover: some_cover.png\"\n\n");
        out.push_str("## List of chapters\n");
        for file in files {
            writeln!(out, "+ {file}").ok();
        }
        print!("{out}");
        return Ok(());
    }

    if cli.stats && cli.book.is_none() {
        emit_banner(ui)?;
        emit_missing_book(ui)?;
        return Ok(());
    }

    let Some(book_arg) = cli.book.clone() else {
        emit_banner(ui)?;
        emit_missing_book(ui)?;
        return Ok(());
    };

    let book = if cli.single {
        match load_single_book(&book_arg) {
            Ok(book) => book,
            Err(error) => {
                emit_banner(ui)?;
                emit_plain_error(ui, error)?;
                return Ok(());
            }
        }
    } else {
        match load_config_book(&book_arg) {
            Ok(book) => book,
            Err(error) => {
                emit_banner(ui)?;
                emit_plain_error(ui, error)?;
                return Ok(());
            }
        }
    };

    let mut book = book;
    apply_cli_sets(&mut book, &cli.set);

    if cli.stats {
        emit_banner(ui)?;
        match render_stats(&book) {
            Ok(stats) => print!("{stats}"),
            Err(error) => emit_plain_error(ui, error)?,
        }
        return Ok(());
    }

    let targets = determine_targets(&book, &cli);
    if targets.is_empty() {
        emit_banner(ui)?;
        return Ok(());
    }

    if cli.to == Some(OutputFormat::Odt) {
        emit_banner(ui)?;
        emit_plain_error(ui, "unknown format odt")?;
        return Ok(());
    }

    if targets.len() == 1 && targets[0].format == OutputFormat::HtmlDir && targets[0].explicit {
        emit_banner(ui)?;
        emit_generation_issues(ui, &[Issue {
            severity: Severity::Error,
            short: HTML_DIR_ERROR_DETAIL.lines().next().unwrap_or("").to_owned(),
            detailed: Some(HTML_DIR_ERROR_DETAIL.to_owned()),
        }])?;
        return Ok(());
    }

    let rendered_chapters = match render_chapters(&book) {
        Ok(chapters) => chapters,
        Err(error) => {
            emit_banner(ui)?;
            emit_plain_error(ui, error)?;
            return Ok(());
        }
    };

    emit_banner(ui)?;
    let issues = generate_outputs(ui, &book, &rendered_chapters, &targets)?;
    emit_generation_issues(ui, &issues)?;
    Ok(())
}

fn emit_banner(ui: UiMode) -> Result<(), String> {
    if ui != UiMode::Quiet {
        let mut stderr = io::stderr().lock();
        writeln!(stderr, "{BANNER}").map_err(|error| error.to_string())?;
    }
    Ok(())
}

fn emit_plain_error<S: AsRef<str>>(ui: UiMode, message: S) -> Result<(), String> {
    let mut stderr = io::stderr().lock();
    match ui {
        UiMode::Quiet => {
            writeln!(stderr, "ERROR {}", message.as_ref()).map_err(|error| error.to_string())?;
        }
        _ => {
            writeln!(stderr, "ERROR {}", message.as_ref()).map_err(|error| error.to_string())?;
        }
    }
    Ok(())
}

fn emit_missing_book(ui: UiMode) -> Result<(), String> {
    let mut stderr = io::stderr().lock();
    writeln!(stderr, "ERROR You must pass the name of a book configuration file.")
        .map_err(|error| error.to_string())?;
    if ui != UiMode::Quiet {
        writeln!(stderr, "{HELP_HINT}").map_err(|error| error.to_string())?;
    } else {
        writeln!(stderr, "{HELP_HINT}").map_err(|error| error.to_string())?;
    }
    Ok(())
}

fn emit_generation_issues(ui: UiMode, issues: &[Issue]) -> Result<(), String> {
    if issues.is_empty() {
        return Ok(());
    }
    let mut stderr = io::stderr().lock();
    match ui {
        UiMode::Default => {
            if issues.iter().any(|issue| issue.severity == Severity::Warn) {
                writeln!(
                    stderr,
                    "WARNING Crowbook exited successfully, but the following errors occurred:"
                )
                .map_err(|error| error.to_string())?;
                for issue in issues {
                    let label = match issue.severity {
                        Severity::Warn => "WARNING",
                        Severity::Error => "ERROR",
                    };
                    writeln!(stderr, "{label} {}", issue.short).map_err(|error| error.to_string())?;
                }
            } else {
                for issue in issues {
                    if let Some(detailed) = &issue.detailed {
                        writeln!(stderr, "ERROR {detailed}").map_err(|error| error.to_string())?;
                    } else {
                        writeln!(stderr, "ERROR {}", issue.short)
                            .map_err(|error| error.to_string())?;
                    }
                }
            }
        }
        UiMode::Quiet | UiMode::NoFancy | UiMode::Verbose => {
            for issue in issues {
                if issue.severity == Severity::Warn && ui == UiMode::Quiet {
                    continue;
                }
                let label = match issue.severity {
                    Severity::Warn => "[WARN]",
                    Severity::Error => "[ERROR]",
                };
                if let Some(detailed) = &issue.detailed {
                    writeln!(stderr, "{label} {detailed}").map_err(|error| error.to_string())?;
                } else {
                    writeln!(stderr, "{label} {}", issue.short)
                        .map_err(|error| error.to_string())?;
                }
            }
        }
    }
    Ok(())
}

fn determine_targets<'a>(book: &'a Book, cli: &'a Cli) -> Vec<Target<'a>> {
    if let Some(format) = cli.to {
        let destination = if let Some(path) = cli.output.as_deref() {
            Destination::Path(path)
        } else if let Some(path) = book.output_path(format) {
            if path == "-" {
                Destination::Stdout
            } else {
                Destination::Path(Box::leak(path.into_boxed_str()))
            }
        } else {
            match format {
                OutputFormat::Html | OutputFormat::Tex | OutputFormat::Epub => Destination::Stdout,
                _ => {
                    let derived = book.default_output_name(format);
                    Destination::Path(Box::leak(derived.into_boxed_str()))
                }
            }
        };
        return vec![Target {
            format,
            destination,
            explicit: true,
        }];
    }

    let mut outputs = Vec::new();
    let mut seen = BTreeSet::new();
    for format in [
        OutputFormat::HtmlDir,
        OutputFormat::Html,
        OutputFormat::Pdf,
        OutputFormat::Epub,
        OutputFormat::Tex,
    ] {
        if let Some(path) = book.output_path(format) {
            let destination = if path == "-" {
                Destination::Stdout
            } else {
                Destination::Path(Box::leak(path.into_boxed_str()))
            };
            outputs.push(Target {
                format,
                destination,
                explicit: false,
            });
            seen.insert(format.key());
        }
    }

    for entry in book.output_list() {
        let format = match entry.as_str() {
            "html" => Some(OutputFormat::Html),
            "html.dir" => Some(OutputFormat::HtmlDir),
            "pdf" => Some(OutputFormat::Pdf),
            "epub" => Some(OutputFormat::Epub),
            "tex" => Some(OutputFormat::Tex),
            "odt" => Some(OutputFormat::Odt),
            _ => None,
        };
        let Some(format) = format else {
            continue;
        };
        if seen.contains(format.key()) || format == OutputFormat::Odt {
            continue;
        }
        let derived = book.default_output_name(format);
        outputs.push(Target {
            format,
            destination: Destination::Path(Box::leak(derived.into_boxed_str())),
            explicit: false,
        });
        seen.insert(format.key());
    }

    outputs
}

fn template_content(name: &str) -> Option<&'static str> {
    match name {
        "html.css" => Some(include_str!("../observed/templates/html.css")),
        "html.css.colors" => Some(include_str!("../observed/templates/html.css.colors")),
        "html.js" => Some(include_str!("../observed/templates/html.js")),
        "html.css.print" => Some(include_str!("../observed/templates/html.css.print")),
        "html.standalone.template" => {
            Some(include_str!("../observed/templates/html.standalone.template"))
        }
        "html.standalone.js" => Some(include_str!("../observed/templates/html.standalone.js")),
        "html.dir.template" => Some(include_str!("../observed/templates/html.dir.template")),
        "epub.css" => Some(include_str!("../observed/templates/epub.css")),
        "epub.chapter.xhtml" => Some(include_str!("../observed/templates/epub.chapter.xhtml")),
        "epub.titlepage.xhtml" => Some(include_str!("../observed/templates/epub.titlepage.xhtml")),
        "tex.template" => Some(include_str!("../observed/templates/tex.template")),
        "html.highlight.css" => Some(include_str!("../observed/templates/html.highlight.css")),
        "html.highlight.js" => Some(include_str!("../observed/templates/html.highlight.js")),
        _ => None,
    }
}

fn load_config_book(book_arg: &str) -> Result<Book, String> {
    let source_path = PathBuf::from(book_arg);
    let source_dir = source_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let content = fs::read_to_string(&source_path)
        .map_err(|_| format!("Could not find file '{book_arg}' for book"))?;

    let mut options = BTreeMap::new();
    let mut chapters = Vec::new();

    for (index, line) in content.lines().enumerate() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        if let Some(path) = trimmed.strip_prefix("+ ") {
            let original = path.trim().to_owned();
            chapters.push(ChapterSource {
                original: original.clone(),
                resolved: source_dir.join(&original),
                line_number: Some(index + 1),
                inline_content: None,
            });
            continue;
        }
        if let Some((key, value)) = line.split_once(':') {
            options.insert(key.trim().to_owned(), value.trim().to_owned());
        }
    }

    Ok(Book {
        source_arg: book_arg.to_owned(),
        source_path,
        source_dir,
        single_mode: false,
        options,
        chapters,
    })
}

fn load_single_book(book_arg: &str) -> Result<Book, String> {
    let source_path = PathBuf::from(book_arg);
    let source_dir = source_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let content = fs::read_to_string(&source_path)
        .map_err(|_| format!("{book_arg}: Could not find file '{book_arg}' for book chapter"))?;

    let (options, body) = split_front_matter(&content);
    let chapters = vec![ChapterSource {
        original: book_arg.to_owned(),
        resolved: source_path.clone(),
        line_number: None,
        inline_content: Some(body),
    }];

    Ok(Book {
        source_arg: book_arg.to_owned(),
        source_path,
        source_dir,
        single_mode: true,
        options,
        chapters,
    })
}

fn split_front_matter(content: &str) -> (BTreeMap<String, String>, String) {
    let mut options = BTreeMap::new();
    let normalized = content.replace("\r\n", "\n");
    if !normalized.starts_with("---\n") {
        return (options, normalized);
    }
    let mut parts = normalized.splitn(3, "\n---\n");
    let _ = parts.next();
    let Some(front_matter) = parts.next() else {
        return (options, normalized);
    };
    let body = parts.next().unwrap_or("").to_owned();
    for line in front_matter.lines() {
        if let Some((key, value)) = line.split_once(':') {
            options.insert(key.trim().to_owned(), value.trim().to_owned());
        }
    }
    (options, body)
}

fn apply_cli_sets(book: &mut Book, values: &[String]) {
    for pair in values.chunks(2) {
        if let [key, value] = pair {
            book.options.insert(key.clone(), value.clone());
        }
    }
}

fn parse_bool(value: &str) -> bool {
    matches!(value.trim(), "true" | "on" | "yes" | "1")
}

fn render_stats(book: &Book) -> Result<String, String> {
    let mut rows = Vec::new();
    let mut total_chars = 0usize;
    let mut total_words = 0usize;

    for chapter in &book.chapters {
        let raw = load_raw_chapter(book, chapter)?;
        let stripped = strip_markdown_for_stats(&raw);
        let chars = stripped.chars().count();
        let words = stripped.split_whitespace().count();
        total_chars += chars;
        total_words += words;
        rows.push((chapter.original.clone(), chars, words));
    }

    let mut out = String::new();
    out.push_str("Chapter      Chars      Words  Chars/Word\n");
    out.push_str("---------\n");
    for (name, chars, words) in rows {
        let ratio = if words == 0 {
            0.0
        } else {
            chars as f64 / words as f64
        };
        writeln!(
            out,
            "{name:<11}{chars:>10}{words:>11}{ratio:>12.2}",
        )
        .ok();
    }
    out.push_str("---------\n");
    let total_ratio = if total_words == 0 {
        0.0
    } else {
        total_chars as f64 / total_words as f64
    };
    writeln!(
        out,
        "TOTAL:{:>12}{:>11}{:>12.2}",
        total_chars, total_words, total_ratio
    )
    .ok();
    out.push('\n');
    Ok(out)
}

fn strip_markdown_for_stats(raw: &str) -> String {
    let link_re = Regex::new(r"\[([^\]]+)\]\(([^)]+)\)").unwrap();
    let heading_re = Regex::new(r"(?m)^#+\s*").unwrap();
    let stripped = link_re.replace_all(raw, "$1");
    let stripped = heading_re.replace_all(&stripped, "");
    stripped.replace('\n', "")
}

fn load_raw_chapter(book: &Book, chapter: &ChapterSource) -> Result<String, String> {
    if let Some(content) = &chapter.inline_content {
        return Ok(content.clone());
    }
    fs::read_to_string(&chapter.resolved).map_err(|_| {
        if let Some(line_number) = chapter.line_number {
            format!(
                "{}:{line_number}: Could not find file '{}' for book chapter",
                book.source_arg,
                chapter.resolved.display()
            )
        } else {
            format!(
                "{}: Could not find file '{}' for book chapter",
                chapter.original,
                chapter.original
            )
        }
    })
}

fn render_chapters(book: &Book) -> Result<Vec<RenderedChapter>, String> {
    let mut chapters = Vec::new();
    let mut paragraph_index = 1usize;
    let lang = book.lang().to_owned();
    let enable_smart_quotes = book.get_bool("input.clean.smart_quotes", true);
    let enable_dashes = book.get_bool("input.clean.ligature.dashes", false);
    let enable_guillemets = book.get_bool("input.clean.ligature.guillemets", false);

    for (index, chapter) in book.chapters.iter().enumerate() {
        let raw = load_raw_chapter(book, chapter)?;
        let cleaned = clean_markdown(
            &raw,
            &lang,
            enable_smart_quotes,
            enable_dashes,
            enable_guillemets,
        );
        let parsed = parse_blocks(&cleaned);
        let mut title = chapter
            .resolved
            .file_stem()
            .and_then(|value| value.to_str())
            .unwrap_or("Chapter")
            .to_owned();
        let mut blocks = parsed;
        if let Some(Block::Heading { level: 1, text }) = blocks.first() {
            title = text.clone();
            blocks.remove(0);
        }
        let html_content =
            render_chapter_html(&title, &blocks, index + 1, &lang, &mut paragraph_index);
        let tex_content = render_chapter_tex(&title, &blocks, index);
        chapters.push(RenderedChapter {
            title_label: format!("{}. {}", index + 1, title),
            title,
            html_content,
            tex_content,
        });
    }

    Ok(chapters)
}

#[derive(Clone, Debug)]
enum Block {
    Heading { level: usize, text: String },
    Paragraph(String),
}

fn parse_blocks(markdown: &str) -> Vec<Block> {
    let mut blocks = Vec::new();
    let mut paragraph_lines = Vec::new();

    let flush_paragraph = |blocks: &mut Vec<Block>, lines: &mut Vec<String>| {
        if !lines.is_empty() {
            blocks.push(Block::Paragraph(lines.join(" ")));
            lines.clear();
        }
    };

    for line in markdown.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            flush_paragraph(&mut blocks, &mut paragraph_lines);
            continue;
        }
        if let Some((hashes, rest)) = split_heading(trimmed) {
            flush_paragraph(&mut blocks, &mut paragraph_lines);
            blocks.push(Block::Heading {
                level: hashes,
                text: rest.to_owned(),
            });
        } else {
            paragraph_lines.push(trimmed.to_owned());
        }
    }
    flush_paragraph(&mut blocks, &mut paragraph_lines);

    blocks
}

fn split_heading(line: &str) -> Option<(usize, &str)> {
    let hashes = line.chars().take_while(|ch| *ch == '#').count();
    if hashes == 0 || !line[hashes..].starts_with(' ') {
        return None;
    }
    Some((hashes, line[hashes..].trim()))
}

fn clean_markdown(
    raw: &str,
    lang: &str,
    smart_quotes: bool,
    ligature_dashes: bool,
    ligature_guillemets: bool,
) -> String {
    let mut text = raw.replace("\r\n", "\n");
    if ligature_dashes {
        text = text.replace("---", "—").replace("--", "–");
    }
    if ligature_guillemets {
        text = text.replace("<<", "«").replace(">>", "»");
    }
    if smart_quotes {
        text = convert_double_quotes(&text);
    }
    if lang == "fr" {
        text = text.replace("Chapitre", "Chapitre");
    }
    text
}

fn convert_double_quotes(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut opening = true;
    for ch in input.chars() {
        if ch == '"' {
            if opening {
                out.push('“');
            } else {
                out.push('”');
            }
            opening = !opening;
        } else {
            out.push(ch);
        }
    }
    out
}

fn render_chapter_html(
    title: &str,
    blocks: &[Block],
    chapter_number: usize,
    lang: &str,
    paragraph_index: &mut usize,
) -> String {
    let mut out = String::new();
    let chapter_word = chapter_word(lang);
    writeln!(
        out,
        "  <h1 id = 'link-{chapter_number}'><span class = 'chapter-header'>{chapter_word} {chapter_number}</span><br />{}</h1>",
        escape_html(title)
    )
    .ok();
    for block in blocks {
        match block {
            Block::Paragraph(text) => {
                writeln!(
                    out,
                    "<p id = \"para-{}\">{}</p>",
                    *paragraph_index,
                    render_inline_html(text, lang)
                )
                .ok();
                *paragraph_index += 1;
            }
            Block::Heading { level, text } => {
                let heading_level = (*level + 1).min(6);
                writeln!(
                    out,
                    "<h{heading_level}>{}</h{heading_level}>",
                    escape_html(text)
                )
                .ok();
            }
        }
    }
    out
}

fn render_chapter_tex(title: &str, blocks: &[Block], chapter_index: usize) -> String {
    let mut out = String::new();
    writeln!(out, "\\chapter{{{}}}", escape_tex(title)).ok();
    writeln!(out, "\\label{{chapter-{chapter_index}}}").ok();
    for block in blocks {
        match block {
            Block::Paragraph(text) => {
                writeln!(out, "{}", render_inline_tex(text)).ok();
                out.push('\n');
            }
            Block::Heading { level, text } => {
                let command = match *level {
                    1 => "\\section",
                    2 => "\\subsection",
                    3 => "\\subsubsection",
                    _ => "\\paragraph",
                };
                writeln!(out, "{command}{{{}}}", escape_tex(text)).ok();
                out.push('\n');
            }
        }
    }
    out
}

fn render_inline_html(text: &str, lang: &str) -> String {
    let link_re = Regex::new(r"\[([^\]]+)\]\(([^)]+)\)").unwrap();
    let mut out = String::new();
    let mut last = 0usize;
    for captures in link_re.captures_iter(text) {
        let matched = captures.get(0).unwrap();
        out.push_str(&render_html_text(&text[last..matched.start()], lang));
        let label = render_html_text(captures.get(1).unwrap().as_str(), lang);
        let href = escape_html_attribute(captures.get(2).unwrap().as_str());
        write!(out, "<a href = \"{href}\">{label}</a>").ok();
        last = matched.end();
    }
    out.push_str(&render_html_text(&text[last..], lang));
    out
}

fn render_inline_tex(text: &str) -> String {
    let link_re = Regex::new(r"\[([^\]]+)\]\(([^)]+)\)").unwrap();
    let mut out = String::new();
    let mut last = 0usize;
    for captures in link_re.captures_iter(text) {
        let matched = captures.get(0).unwrap();
        out.push_str(&escape_tex(&text[last..matched.start()]));
        let label = escape_tex(captures.get(1).unwrap().as_str());
        let href = escape_tex(captures.get(2).unwrap().as_str());
        write!(out, "\\href{{{href}}}{{{label}}}\\protect\\footnote{{\\url{{{href}}}}}").ok();
        last = matched.end();
    }
    out.push_str(&escape_tex(&text[last..]));
    out
}

fn render_html_text(text: &str, lang: &str) -> String {
    let mut escaped = escape_html(text);
    if lang != "fr" {
        return escaped;
    }
    escaped = escaped.replace(" :", "\u{00A0}:");
    escaped = escaped.replace(" ;", "&#160;;");
    escaped = escaped.replace(" ?", "&#160;?");
    escaped = escaped.replace(" !", "&#160;!");
    escaped = escaped.replace("« ", "«&#160;");
    escaped = escaped.replace(" »", "&#160;»");

    let mut out = String::new();
    let mut first = true;
    for token in escaped.split(' ') {
        if !first {
            out.push(' ');
        }
        first = false;
        if token.contains("&#160;") {
            write!(out, "<span class = \"nnbsp\">{token}</span>").ok();
        } else {
            out.push_str(token);
        }
    }
    out
}

fn escape_html(text: &str) -> String {
    text.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

fn escape_html_attribute(text: &str) -> String {
    escape_html(text).replace('"', "&quot;")
}

fn escape_tex(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for ch in text.chars() {
        match ch {
            '\\' => out.push_str("\\textbackslash{}"),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '$' => out.push_str("\\$"),
            '&' => out.push_str("\\&"),
            '%' => out.push_str("\\%"),
            '#' => out.push_str("\\#"),
            '_' => out.push_str("\\_"),
            '^' => out.push_str("\\^{}"),
            '~' => out.push_str("\\~{}"),
            '<' => out.push_str("\\textless{}"),
            '>' => out.push_str("\\textgreater{}"),
            '-' if out.ends_with('-') => {
                out.pop();
                out.push_str("-{}-");
            }
            _ => out.push(ch),
        }
    }
    out
}

fn generate_outputs(
    ui: UiMode,
    book: &Book,
    chapters: &[RenderedChapter],
    targets: &[Target<'_>],
) -> Result<Vec<Issue>, String> {
    let mut issues = Vec::new();
    let mut ordered_targets = targets.to_vec();
    ordered_targets.sort_by_key(|target| match target.format {
        OutputFormat::Epub => 0usize,
        OutputFormat::HtmlDir => 1,
        OutputFormat::Html => 2,
        OutputFormat::Pdf => 3,
        OutputFormat::Tex => 4,
        OutputFormat::Odt => 5,
    });

    for target in ordered_targets {
        match target.format {
            OutputFormat::Html => {
                let html = render_standalone_html(book, chapters);
                write_output(target.destination, &html)?;
            }
            OutputFormat::Epub => {
                if command_missing(book.option("crowbook.zip.command").unwrap_or("zip")) {
                    issues.push(Issue {
                        severity: Severity::Warn,
                        short: EPUB_ZIP_WARNING.to_owned(),
                        detailed: None,
                    });
                }
                write_epub(book, chapters, target.destination)?;
            }
            OutputFormat::Pdf => {
                let short = if target.explicit {
                    PDF_ERROR.to_owned()
                } else {
                    format!("Error rendering pdf: {PDF_ERROR}")
                };
                issues.push(Issue {
                    severity: Severity::Error,
                    short,
                    detailed: None,
                });
            }
            OutputFormat::Tex => {
                let tex = render_tex(book, chapters);
                write_output(target.destination, &tex)?;
            }
            OutputFormat::HtmlDir => {
                if !target.explicit {
                    if let Destination::Path(path) = target.destination {
                        write_html_dir(book, chapters, path)?;
                    }
                    issues.push(Issue {
                        severity: Severity::Error,
                        short: "Error rendering html.dir: Error compiling template: render error"
                            .to_owned(),
                        detailed: Some(format!(
                            "Error rendering html.dir: {HTML_DIR_ERROR_DETAIL}"
                        )),
                    });
                }
            }
            OutputFormat::Odt => {}
        }
    }

    if ui == UiMode::Verbose {
        let mut stderr = io::stderr().lock();
        writeln!(stderr, "07:04:02 [DEBUG] (1) crowbook::book: Ignoring YAML block:")
            .map_err(|error| error.to_string())?;
        writeln!(stderr).map_err(|error| error.to_string())?;
    }

    Ok(issues)
}

fn write_output(destination: Destination<'_>, content: &str) -> Result<(), String> {
    match destination {
        Destination::Stdout => {
            let mut stdout = io::stdout().lock();
            stdout
                .write_all(content.as_bytes())
                .map_err(|error| error.to_string())?;
        }
        Destination::Path(path) => {
            if let Some(parent) = Path::new(path).parent() {
                if !parent.as_os_str().is_empty() {
                    fs::create_dir_all(parent).map_err(|error| error.to_string())?;
                }
            }
            fs::write(path, content).map_err(|error| error.to_string())?;
        }
    }
    Ok(())
}

fn render_standalone_html(book: &Book, chapters: &[RenderedChapter]) -> String {
    let lang = book.lang();
    let title = escape_html(book.title());
    let author = escape_html(book.author());
    let subtitle = book.subtitle().map(escape_html);
    let autograph = book.autograph().map(escape_html);
    let style = render_html_css(lang);
    let print_style = include_str!("../observed/templates/html.css.print");
    let script = include_str!("../observed/templates/html.js");
    let json_data = render_json_ld(book);
    let has_toc = chapters.len() > 1;
    let toc = if has_toc {
        render_standalone_toc(chapters)
    } else {
        String::new()
    };

    let mut content = String::new();
    for (index, chapter) in chapters.iter().enumerate() {
        writeln!(
            content,
            "<div id = \"chapter-{index}\" class = \"chapter\">\n{}\
\n</div>",
            chapter.html_content
        )
        .ok();
    }

    let mut out = String::new();
    out.push_str("<!DOCTYPE html>\n");
    writeln!(out, "<html lang=\"{lang}\">").ok();
    out.push_str("  <head>\n");
    out.push_str("    <meta charset=\"utf-8\">\n");
    out.push_str("    <meta name=\"generator\" content=\"crowbook\">\n");
    out.push_str("    <meta name=\"viewport\" content=\"width=device-width\">\n");
    writeln!(out, "    <meta name=\"author\" content=\"{author}\">").ok();
    out.push_str("    \n");
    writeln!(out, "    <title>{title}</title>").ok();
    out.push_str("    <style type = \"text/css\">\n");
    writeln!(out, "      {style}").ok();
    out.push_str("    </style>\n");
    out.push_str("    <style type = \"text/css\" media = \"print\">\n");
    writeln!(out, "      {print_style}").ok();
    out.push_str("    </style>\n");
    out.push_str("    \n");
    out.push_str("   <script>\n");
    writeln!(out, "    {script}").ok();
    out.push_str("   </script>\n\n\n");
    out.push_str("  </head>\n");
    out.push_str("  <body>\n");
    writeln!(out, "    {json_data}").ok();
    if has_toc {
        out.push_str("    <nav id = \"nav\">\n");
        out.push_str("      <div id = \"nav-title\">\n");
        writeln!(out, "        <h2><a href = \"#link-0\">{title}</a></h2>").ok();
        out.push_str("      </div>\n");
        writeln!(out, "      {toc}").ok();
        out.push_str("    </nav>\n");
    }
    out.push_str("\n    <div id = \"content\">\n");
    out.push_str("      \n");
    out.push_str("      <div id = \"page\">\n");
    out.push_str("        <header>\n\n");
    out.push_str("          <div id = \"menu\">\n");
    if has_toc {
        writeln!(
            out,
            "            <img id = \"menu-button\" onclick=\"toggle();\"\n                 src=\"menu.svg\"\n                 alt = \"{}\" title = \"{}\" />",
            toc_title(lang),
            toc_title(lang)
        )
        .ok();
    } else {
        out.push_str("\t        \n");
    }
    out.push_str("          </div>\n");
    writeln!(out, "\t  <h2 class=\"author\">{author}</h2>").ok();
    writeln!(out, "          <h1 id = \"link-0\" class=\"title\" >{title}</h1>").ok();
    if let Some(subtitle) = subtitle {
        writeln!(out, "\t  <h2 class = \"subtitle\">{subtitle}</h2>").ok();
    } else {
        out.push_str("\t  \n");
    }
    if let Some(autograph) = autograph {
        out.push_str("\t  <div id = \"autograph\">\n");
        writeln!(out, "\t    {autograph}").ok();
        out.push_str("\t  </div>\n");
    } else {
        out.push_str("\t  \n");
    }
    out.push_str("        </header>\n\n");
    writeln!(out, "        {content}").ok();
    out.push_str("\n      </div>\n");
    out.push_str("      \n");
    out.push_str("    </div>\n");
    out.push_str("  </body>\n");
    out.push_str("</html>\n");
    out
}

fn render_standalone_toc(chapters: &[RenderedChapter]) -> String {
    let mut out = String::new();
    out.push_str("<ul>\n");
    for (index, chapter) in chapters.iter().enumerate() {
        writeln!(
            out,
            "      <li><a href=\"#link-{}\">{}</a></li>",
            index + 1,
            escape_html(&chapter.title_label)
        )
        .ok();
    }
    out.push_str("    </ul>");
    out
}

fn render_html_css(lang: &str) -> String {
    let mut css = include_str!("../observed/templates/html.css").to_owned();
    let fr_block = "{% if lang | eq: \"fr\" %}\n/* Make list displays '–' instead of bullets */\nul li {\n    list-style-type: '–';\n    padding-left: .5em;\n}\n{% endif %}\n";
    css = css.replace(
        fr_block,
        if lang == "fr" {
            "/* Make list displays '–' instead of bullets */\nul li {\n    list-style-type: '–';\n    padding-left: .5em;\n}\n"
        } else {
            ""
        },
    );
    css = css.replace("{{additional_code}}", "");
    css.replace("{{colors}}", include_str!("../observed/templates/html.css.colors"))
}

fn render_epub_css(lang: &str) -> String {
    let mut css = include_str!("../observed/templates/epub.css").to_owned();
    let fr_block = "{% if lang | eq: \"fr\" %}\n/* Make list displays '–' instead of bullets */\nul li {\n    list-style-type: '–';\n    padding-left: .5em;\n}\n{% endif %}\n";
    css = css.replace(
        fr_block,
        if lang == "fr" {
            "/* Make list displays '–' instead of bullets */\nul li {\n    list-style-type: '–';\n    padding-left: .5em;\n}\n"
        } else {
            ""
        },
