    css.replace("{{additional_code}}", "")
}

fn render_json_ld(book: &Book) -> String {
    format!(
        "<script type = 'application/ld+json'>\n{{\n    \"@context\": \"http://schema.org/\",\n    \"@type\": \"Book\",\n    \"author\": \"{}\",\n    \"name\": \"{}\",\n    \n    \n    \n    \n    \n    \"inLanguage\": \"{}\"\n}}\n</script>",
        escape_html(book.author()),
        escape_html(book.title()),
        book.lang()
    )
}

fn write_epub(book: &Book, chapters: &[RenderedChapter], destination: Destination<'_>) -> Result<(), String> {
    let mut buffer = Vec::new();
    {
        let cursor = io::Cursor::new(&mut buffer);
        let mut zip = ZipWriter::new(cursor);
        let stored: FileOptions<'_, ()> =
            FileOptions::default().compression_method(CompressionMethod::Stored);
        let deflated: FileOptions<'_, ()> =
            FileOptions::default().compression_method(CompressionMethod::Deflated);

        zip.start_file("mimetype", stored)
            .map_err(|error| error.to_string())?;
        zip.write_all(b"application/epub+zip")
            .map_err(|error| error.to_string())?;

        write_zip_file(
            &mut zip,
            "META-INF/container.xml",
            render_container_xml().as_bytes(),
            deflated,
        )?;
        write_zip_file(
            &mut zip,
            "META-INF/com.apple.ibooks.display-options.xml",
            render_ibooks_display_options().as_bytes(),
            deflated,
        )?;
        write_zip_file(
            &mut zip,
            "OEBPS/title_page.xhtml",
            render_epub_title_page(book).as_bytes(),
            deflated,
        )?;
        for (index, chapter) in chapters.iter().enumerate() {
            let path = format!("OEBPS/chapter_{index:03}.xhtml");
            write_zip_file(
                &mut zip,
                &path,
                render_epub_chapter(book, chapter).as_bytes(),
                deflated,
            )?;
        }
        write_zip_file(
            &mut zip,
            "OEBPS/stylesheet.css",
            render_epub_css(book.lang()).as_bytes(),
            deflated,
        )?;
        write_zip_file(
            &mut zip,
            "OEBPS/content.opf",
            render_opf(book, chapters).as_bytes(),
            deflated,
        )?;
        write_zip_file(
            &mut zip,
            "OEBPS/toc.ncx",
            render_toc_ncx(book, chapters).as_bytes(),
            deflated,
        )?;
        write_zip_file(
            &mut zip,
            "OEBPS/nav.xhtml",
            render_nav_xhtml(book, chapters).as_bytes(),
            deflated,
        )?;
        zip.finish().map_err(|error| error.to_string())?;
    }

    match destination {
        Destination::Stdout => {
            let mut stdout = io::stdout().lock();
            stdout.write_all(&buffer).map_err(|error| error.to_string())?;
        }
        Destination::Path(path) => {
            if let Some(parent) = Path::new(path).parent() {
                if !parent.as_os_str().is_empty() {
                    fs::create_dir_all(parent).map_err(|error| error.to_string())?;
                }
            }
            fs::write(path, buffer).map_err(|error| error.to_string())?;
        }
    }
    Ok(())
}

fn write_zip_file<W: Write + io::Seek>(
    zip: &mut ZipWriter<W>,
    name: &str,
    bytes: &[u8],
    options: FileOptions<'_, ()>,
) -> Result<(), String> {
    zip.start_file(name, options)
        .map_err(|error| error.to_string())?;
    zip.write_all(bytes).map_err(|error| error.to_string())?;
    Ok(())
}

fn render_container_xml() -> String {
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<container version=\"1.0\" xmlns=\"urn:oasis:names:tc:opendocument:xmlns:container\">\n  <rootfiles>\n    <rootfile full-path=\"OEBPS/content.opf\" media-type=\"application/oebps-package+xml\" />\n  </rootfiles>\n</container>\n".to_owned()
}

fn render_ibooks_display_options() -> String {
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<display_options>\n  <platform name=\"*\">\n    <option name=\"specified-fonts\">true</option>\n  </platform>\n</display_options>\n".to_owned()
}

fn render_epub_title_page(book: &Book) -> String {
    let lang = book.lang();
    let title = escape_html(book.title());
    let author = escape_html(book.author());
    let subtitle = book.subtitle().map(escape_html);
    let autograph = book.autograph().map(escape_html);

    let mut out = String::new();
    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    out.push_str("<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n");
    writeln!(out, "<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"{lang}\">").ok();
    out.push_str("<head>\n");
    out.push_str("  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n");
    out.push_str("  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n");
    out.push_str("  <meta name=\"generator\" content=\"crowbook\" />\n");
    writeln!(out, "  <title>{title}</title>").ok();
    out.push_str("  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n");
    out.push_str("</head>\n");
    out.push_str("<body>\n");
    writeln!(out, "  <h2 class=\"author\">{author}</h2>").ok();
    writeln!(out, "  <h1 class=\"title\">{title}</h1>").ok();
    if let Some(subtitle) = subtitle {
        writeln!(out, "  <h2 class = \"subtitle\">{subtitle}</h2>").ok();
    } else {
        out.push_str("  \n");
    }
    if let Some(autograph) = autograph {
        writeln!(out, "  <div id = \"autograph\">{autograph}</div>").ok();
    } else {
        out.push_str("  \n");
    }
    out.push_str("</body>\n");
    out.push_str("</html>\n");
    out
}

fn render_epub_chapter(book: &Book, chapter: &RenderedChapter) -> String {
    let lang = book.lang();
    let mut out = String::new();
    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    out.push_str("<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n");
    writeln!(
        out,
        "<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"{lang}\" lang=\"{lang}\">"
    )
    .ok();
    out.push_str("  <head>\n");
    out.push_str("  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n");
    out.push_str("  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n");
    out.push_str("  <meta name=\"generator\" content=\"crowbook\" />\n");
    writeln!(out, "  <title>{}</title>", escape_html(&chapter.title_label)).ok();
    out.push_str("  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n");
    out.push_str("  </head>\n");
    writeln!(out, "  <body xml:lang=\"{lang}\" lang=\"{lang}\">").ok();
    out.push_str("    <div id = \"page\">\n");
    writeln!(out, "{}", chapter.html_content).ok();
    out.push_str("    </div>\n");
    out.push_str("  </body>\n");
    out.push_str("</html>\n");
    out
}

fn render_nav_xhtml(book: &Book, chapters: &[RenderedChapter]) -> String {
    let lang = book.lang();
    let toc = toc_title(lang);
    let title_label = title_page_label(lang);
    if book.epub_version() == 3 {
        let mut out = String::new();
        out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
        out.push_str("<!DOCTYPE html>\n");
        out.push_str("<html xmlns=\"http://www.w3.org/1999/xhtml\" xmlns:epub=\"http://www.idpf.org/2007/ops\">\n");
        out.push_str("<head>\n");
        out.push_str("  <meta charset = \"utf-8\" />\n");
        out.push_str("  <meta name=\"generator\" content=\"crowbook\" />\n");
        writeln!(out, "  <title>{toc}</title>").ok();
        out.push_str("  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n");
        out.push_str("</head>\n");
        out.push_str("<body>\n");
        out.push_str("  <nav epub:type = \"toc\" id=\"toc\">\n");
        writeln!(out, "    <h1 id=\"toc-title\">{toc}</h1>").ok();
        out.push_str("    <ol>\n");
        writeln!(out, "      <li><a href=\"title_page.xhtml\">{title_label}</a></li>").ok();
        for (index, chapter) in chapters.iter().enumerate() {
            writeln!(
                out,
                "      <li><a href=\"chapter_{index:03}.xhtml\">{}</a></li>",
                escape_html(&chapter.title_label)
            )
            .ok();
        }
        out.push_str("    </ol>\n");
        out.push_str("  </nav>\n");
        out.push_str("  <nav epub:type = \"landmarks\">\n");
        out.push_str("    <ol>\n");
        writeln!(
            out,
            "      <li><a epub:type=\"titlepage\" href=\"title_page.xhtml\">{title_label}</a></li>"
        )
        .ok();
        for (index, chapter) in chapters.iter().enumerate() {
            writeln!(
                out,
                "      <li><a epub:type=\"bodymatter\" href=\"chapter_{index:03}.xhtml\">{}</a></li>",
                escape_html(&chapter.title_label)
            )
            .ok();
        }
        out.push_str("    </ol>\n");
        out.push_str("  </nav>\n");
        out.push_str("</body>\n");
        out.push_str("</html>\n");
        return out;
    }

    let mut out = String::new();
    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    out.push_str("<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n");
    out.push_str("<html xmlns=\"http://www.w3.org/1999/xhtml\">\n");
    out.push_str("<head>\n");
    out.push_str("  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n");
    out.push_str("  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n");
    out.push_str("  <meta name=\"generator\" content=\"crowbook\" />\n");
    writeln!(out, "  <title>{toc}</title>").ok();
    out.push_str("  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n");
    out.push_str("</head>\n");
    out.push_str("<body>\n");
    out.push_str("  <div id=\"toc\">\n");
    writeln!(out, "    <h1 id=\"toc-title\">{toc}</h1>").ok();
    out.push_str("    <ol>\n");
    writeln!(out, "      <li><a href=\"title_page.xhtml\">{title_label}</a></li>").ok();
    for (index, chapter) in chapters.iter().enumerate() {
        writeln!(
            out,
            "      <li><a href=\"chapter_{index:03}.xhtml\">{}</a></li>",
            escape_html(&chapter.title_label)
        )
        .ok();
    }
    out.push_str("    </ol>\n");
    out.push_str("  </div>\n");
    out.push_str("</body>\n");
    out.push_str("</html>\n");
    out
}

fn render_toc_ncx(book: &Book, chapters: &[RenderedChapter]) -> String {
    let mut out = String::new();
    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    out.push_str("<ncx version=\"2005-1\" xmlns=\"http://www.daisy.org/z3986/2005/ncx/\">\n");
    out.push_str("  <head>\n");
    out.push_str("    <meta name=\"dtb:depth\" content=\"1\" />\n");
    out.push_str("    <meta name=\"dtb:totalPageCount\" content=\"0\" />\n");
    out.push_str("    <meta name=\"dtb:maxPageNumber\" content=\"0\" />\n");
    out.push_str("  </head>\n");
    out.push_str("  <docTitle>\n");
    writeln!(out, "    <text>{}</text>", toc_title(book.lang())).ok();
    out.push_str("  </docTitle>\n");
    out.push_str("  <navMap>\n");
    out.push_str("    <navPoint playOrder=\"1\" id=\"navPoint-1\">\n");
    out.push_str("      <navLabel>\n");
    writeln!(out, "       <text>{}</text>", title_page_label(book.lang())).ok();
    out.push_str("      </navLabel>\n");
    out.push_str("      <content src=\"title_page.xhtml\"/>\n");
    out.push_str("    </navPoint>\n");
    for (index, chapter) in chapters.iter().enumerate() {
        let order = index + 2;
        writeln!(out, "    <navPoint playOrder=\"{order}\" id=\"navPoint-{order}\">").ok();
        out.push_str("      <navLabel>\n");
        writeln!(out, "       <text>{}</text>", escape_html(&chapter.title_label)).ok();
        out.push_str("      </navLabel>\n");
        writeln!(out, "      <content src=\"chapter_{index:03}.xhtml\"/>").ok();
        out.push_str("    </navPoint>\n");
    }
    out.push_str("  </navMap>\n");
    out.push_str("</ncx>\n");
    out
}

fn render_opf(book: &Book, chapters: &[RenderedChapter]) -> String {
    let uuid = format!("urn:uuid:{}", Uuid::new_v4());
    let version = book.epub_version();
    let lang = book.lang();
    let mut out = String::new();
    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    if version == 3 {
        out.push_str("<package version=\"3.0\" xmlns=\"http://www.idpf.org/2007/opf\" unique-identifier=\"epub-id-1\">\n");
    } else {
        out.push_str("<package version=\"2.0\" xmlns=\"http://www.idpf.org/2007/opf\" unique-identifier=\"epub-id-1\">\n");
    }
    out.push_str("  <metadata xmlns:dc=\"http://purl.org/dc/elements/1.1/\"\n");
    out.push_str("            xmlns:opf=\"http://www.idpf.org/2007/opf\">\n");
    writeln!(out, "    <dc:identifier id=\"epub-id-1\">{uuid}</dc:identifier>").ok();
    writeln!(out, "    <dc:title>{}</dc:title>", escape_html(book.title())).ok();
    out.push_str("    \n");
    out.push_str("    \n");
    if version == 3 {
        writeln!(out, "    <dc:language id=\"epub-creator-0\">{lang}</dc:language>").ok();
    } else {
        writeln!(out, "    <dc:language>{lang}</dc:language>").ok();
    }
    out.push_str("    \n");
    out.push_str("    \n");
    out.push_str("    \n");
    if version == 3 {
        writeln!(
            out,
            "    <dc:creator id=\"epub-creator-0\">{}</dc:creator>",
            escape_html(book.author())
        )
        .ok();
        out.push_str("    <meta refines=\"#epub-creator-0\" property=\"role\" scheme=\"marc:relators\">aut</meta>\n");
    } else {
        writeln!(
            out,
            "    <dc:creator opf:role=\"aut\">{}</dc:creator>",
            escape_html(book.author())
        )
        .ok();
    }
    out.push_str("    \n");
    if version == 3 {
        writeln!(
            out,
            "    <meta property=\"dcterms:modified\">{}</meta>",
            Utc::now().format("%Y-%m-%dT%H:%M:%SZ")
        )
        .ok();
        out.push_str("\n");
    } else {
        out.push_str("    \n");
    }
    out.push_str("  </metadata>\n");
    out.push_str("  <manifest>\n");
    out.push_str("    <item id=\"ncx\" href=\"toc.ncx\" media-type=\"application/x-dtbncx+xml\"/>\n");
    if version == 3 {
        out.push_str(
            "    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\" properties=\"nav\"/>\n",
        );
    } else {
        out.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\"/>\n");
    }
    out.push_str("    <item media-type=\"application/xhtml+xml\" id=\"id_title_page.xhtml\" href=\"title_page.xhtml\"/>\n");
    for (index, _) in chapters.iter().enumerate() {
        writeln!(
            out,
            "    <item media-type=\"application/xhtml+xml\" id=\"id_chapter_{index:03}.xhtml\" href=\"chapter_{index:03}.xhtml\"/>"
        )
        .ok();
    }
    out.push_str("    <item media-type=\"text/css\" id=\"id_stylesheet.css\" href=\"stylesheet.css\"/>\n");
    out.push_str("  </manifest>\n");
    if version == 3 {
        out.push_str("  <spine toc=\"ncx\" page-progression-direction=\"ltr\">\n");
    } else {
        out.push_str("  <spine toc=\"ncx\">\n");
    }
    out.push_str("    <itemref idref=\"id_title_page.xhtml\"/>\n");
    for (index, _) in chapters.iter().enumerate() {
        writeln!(out, "    <itemref idref=\"id_chapter_{index:03}.xhtml\"/>").ok();
    }
    out.push_str("  </spine>\n");
    out.push_str("  <guide>\n");
    writeln!(
        out,
        "    <reference type=\"toc\" title=\"{}\" href=\"nav.xhtml\"/>",
        toc_title(book.lang())
    )
    .ok();
    writeln!(
        out,
        "    <reference type=\"title-page\" title=\"{}\" href=\"title_page.xhtml\"/>",
        title_page_label(book.lang())
    )
    .ok();
    for (index, chapter) in chapters.iter().enumerate() {
        writeln!(
            out,
            "    <reference type=\"text\" title=\"{}\" href=\"chapter_{index:03}.xhtml\"/>",
            escape_html(&chapter.title_label)
        )
        .ok();
    }
    out.push_str("  </guide>\n");
    out.push_str("</package>\n");
    out
}

fn write_html_dir(book: &Book, chapters: &[RenderedChapter], path: &str) -> Result<(), String> {
    let directory = Path::new(path);
    if directory.exists() {
        fs::remove_dir_all(directory).map_err(|error| error.to_string())?;
    }
    fs::create_dir_all(directory).map_err(|error| error.to_string())?;
    fs::write(directory.join("stylesheet.css"), render_html_css(book.lang()))
        .map_err(|error| error.to_string())?;
    fs::write(
        directory.join("print.css"),
        include_str!("../observed/templates/html.css.print"),
    )
    .map_err(|error| error.to_string())?;
    for (index, chapter) in chapters.iter().enumerate() {
        let file_name = format!("chapter_{index:03}.html");
        fs::write(directory.join(file_name), render_html_dir_chapter(book, chapters, chapter, index))
            .map_err(|error| error.to_string())?;
    }
    Ok(())
}

fn render_html_dir_chapter(
    book: &Book,
    chapters: &[RenderedChapter],
    chapter: &RenderedChapter,
    chapter_index: usize,
) -> String {
    let lang = book.lang();
    let script = include_str!("../observed/templates/html.js");
    let json_data = render_json_ld(book);
    let mut out = String::new();
    out.push_str("<!DOCTYPE html>\n");
    writeln!(out, "<html lang=\"{lang}\">").ok();
    out.push_str("  <head>\n");
    out.push_str("    <meta charset=\"utf-8\">\n");
    out.push_str("    <meta name=\"generator\" content=\"crowbook\">\n");
    writeln!(
        out,
        "    <meta name=\"author\" content=\"{}\">",
        escape_html(book.author())
    )
    .ok();
    out.push_str("    <meta name=\"viewport\" content=\"width=device-width\">\n");
    out.push_str("    \n");
    writeln!(
        out,
        "    <title>{} - {}</title>",
        escape_html(book.title()),
        escape_html(&chapter.title_label)
    )
    .ok();
    out.push_str("    <link rel = \"stylesheet\" href = \"stylesheet.css\" type = \"text/css\"\n");
    out.push_str("          />\n");
    out.push_str("    <link rel = \"stylesheet\" href = \"print.css\" type = \"text/css\"\n");
    out.push_str("          media = \"print\" />\n");
    out.push_str("    \n");
    out.push_str("   <script>\n");
    writeln!(out, "{script}").ok();
    out.push_str("   </script>\n\n\n");
    out.push_str("  </head>  \n");
    out.push_str("  <body>\n");
    writeln!(out, "  {json_data}").ok();
    out.push_str("  <nav id = \"nav\">\n");
    writeln!(
        out,
        "    <h2><a href = \"index.html\">{}</a></h2>",
        escape_html(book.title())
    )
    .ok();
    writeln!(out, "    {}", render_html_dir_toc(chapters)).ok();
    out.push_str("  </nav>\n\n");
    out.push_str("  <div id = \"content\">\n");
    out.push_str("    \n");
    out.push_str("    <div id = \"page\">\n");
    out.push_str("      <header>\n");
    out.push_str("        <div id = \"menu\">\n");
    writeln!(
        out,
        "\t  <img id = \"menu-button\" onclick=\"toggle();\"\n               src=\"menu.svg\" alt = \"{}\" title = \"{}\" />",
        toc_title(lang),
        toc_title(lang)
    )
    .ok();
    out.push_str("        </div>\n");
    out.push_str("      </header>\n");
    if chapter_index > 0 {
        writeln!(
            out,
            "      <p class = \"prev_chapter\"><a href = \"chapter_{:03}.html\">{}</a></p>",
            chapter_index - 1,
            escape_html(&chapters[chapter_index - 1].title_label)
        )
        .ok();
    } else {
        out.push_str("      \n");
    }
    writeln!(out, "{}", chapter.html_content).ok();
    if chapter_index + 1 < chapters.len() {
        writeln!(
            out,
            "      <p class = \"next_chapter\"><a href = \"chapter_{:03}.html\">{}</a></p>",
            chapter_index + 1,
            escape_html(&chapters[chapter_index + 1].title_label)
        )
        .ok();
    } else {
        out.push_str("\n");
    }
    out.push_str("    </div>\n");
    out.push_str("    \n");
    out.push_str("  </div>\n");
    out.push_str("  </body>\n");
    out.push_str("</html>\n");
    out
}

fn render_html_dir_toc(chapters: &[RenderedChapter]) -> String {
    let mut out = String::new();
    out.push_str("<ul>\n");
    for (index, chapter) in chapters.iter().enumerate() {
        writeln!(
            out,
            "      <li><a href=\"chapter_{index:03}.html#link-{}\">{}</a></li>",
            index + 1,
            escape_html(&chapter.title_label)
        )
        .ok();
    }
    out.push_str("    </ul>");
    out
}

fn render_tex(book: &Book, chapters: &[RenderedChapter]) -> String {
    let class = book.tex_class();
    let lang = match book.lang() {
        "fr" => "french",
        _ => "english",
    };
    let title = escape_tex(book.title());
    let author = escape_tex(book.author());
    let description = escape_tex(book.option("description").unwrap_or(""));

    let mut out = String::new();
    writeln!(out, "\\documentclass{{{class}}}").ok();
    out.push_str("\n%% Package inclusion\n\n");
    out.push_str("% Unicode support if xelatex is used\n");
    out.push_str("\\usepackage{fontspec}\n");
    out.push_str("\\usepackage{xunicode}\n\n\n");
    writeln!(out, "\\usepackage[{lang}]{{babel}} % Language support").ok();
    out.push_str("\\usepackage{fancyhdr} % Headers\n");
    out.push_str("\\usepackage{enumitem}\n\n");
    out.push_str("% Allows hyphenatations in \\texttt\n");
    out.push_str("\\usepackage[htt]{hyphenat}\n\n\n\n");
    out.push_str("% Set hyperlinks and metadata\n");
    out.push_str("\\usepackage[colorlinks=true,breaklinks=true,hypertexnames=false]{hyperref}\n");
    writeln!(out, "\\hypersetup{{pdfauthor={{{author}}},").ok();
    writeln!(out, "  pdftitle={{{title}}},").ok();
    writeln!(out, "  pdfsubject={{{description}}}").ok();
    out.push_str("}\n\n\n\n\n\n\n");
    writeln!(
        out,
        "% Included if the stdpage option if set to false\n\\usepackage[{},{},\n  left={},right={}]{{geometry}} % Set dimensions/margins of the page",
        book.tex_paper_size(),
        format!(
            " top={}, bottom={}",
            book.tex_margin_top(),
            book.tex_margin_bottom()
        ),
        book.tex_margin_left(),
        book.tex_margin_right()
    )
    .ok();
    out.push_str("\n\n\n\n\n\n");
    out.push_str("\\makeatletter\n");
    out.push_str("\\date{}\n\n");
    if class == "book" {
        out.push_str("  \n% Redefine the \\maketitle command, only for book class (not used if stdpage option is set to true)\n");
        out.push_str("\\renewcommand{\\maketitle}{\n  \n\n  % First page with only the title\n  \\thispagestyle{empty}\n  \\vspace*{\\stretch{1}}\n\n  \\begin{center}\n    {\\Huge \\@title   \\\\[5mm]}\n  \\end{center}\n  \\vspace*{\\stretch{2}}\n\n  \\newpage\n  % Empty left page\n  \\thispagestyle{empty}\n  \\cleardoublepage\n\n  % Main title page, with author, title, subtitle, date\n  \\begin{center}\n    \\thispagestyle{empty}\n    \\vspace*{\\baselineskip}\n    \\rule{\\textwidth}{1.6pt}\\vspace*{-\\baselineskip}\\vspace*{2pt}\n    \\rule{\\textwidth}{0.4pt}\\\\[\\baselineskip]\n\n    {\\Huge\\scshape \\@title   \\\\[5mm]}\n    {\\Large }\n\n    \\rule{\\textwidth}{0.4pt}\\vspace*{-\\baselineskip}\\vspace{3.2pt}\n    \\rule{\\textwidth}{1.6pt}\\\\[\\baselineskip]\n\n    \\vspace*{4\\baselineskip}\n\n    {\\Large \\@author}\n      \n    \\vfill\n      \n  \\end{center}\n\n  \\pagebreak\n  \\newpage\n  % Copyright page with author, version, and license\n  \\thispagestyle{empty}\n  \\null\\vfill\n  \\noindent\n  \\begin{center}\n    {\\emph{\\@title}, © \\@author.\\\\[5mm]}\n    \n  \\end{center}\n  \\pagebreak\n  \\newpage\n}\n  \n\n");
    }
    out.push_str("% Redefine headers\n");
    out.push_str("\\pagestyle{fancy}\n");
    out.push_str("\\fancyhead{}\n");
    out.push_str("\\fancyhead[CO,CE]{\\thepage}\n");
    out.push_str("\\fancyfoot{}\n\n\n\n\n");
    out.push_str("\\makeatother\n\n");
    writeln!(out, "\\title{{{title}}}").ok();
    writeln!(out, "\\author{{{author}}}").ok();
    out.push_str("\n\\begin{document}\n\n");
    out.push_str("% Redefine chapter and part names if they needs to be\n");
    out.push_str("% Needs to be after \\begin{document} because babel\n\n\n\n\n\n");
    out.push_str("\\maketitle\n\n\n\n\n");
    for chapter in chapters {
        writeln!(out, "{}", chapter.tex_content).ok();
        out.push('\n');
    }
    out.push_str("\\end{document}\n");
    out
}

fn command_missing(command: &str) -> bool {
    let path_var = std::env::var_os("PATH");
    let Some(path_var) = path_var else {
        return true;
    };
    std::env::split_paths(&path_var).all(|directory| !directory.join(command).exists())
}

fn chapter_word(lang: &str) -> &'static str {
    match lang {
        "fr" => "Chapitre",
        _ => "Chapter",
    }
}

fn toc_title(lang: &str) -> &'static str {
    match lang {
        "fr" => "Table des matières",
        _ => "Table of contents",
    }
}

fn title_page_label(lang: &str) -> &'static str {
    match lang {
        "fr" => "Titre",
        _ => "Title",
    }
}

