          Prints the default content of a template
  -S, --stats
          Print some project statistics
  -h, --help
          Print help
  -V, --version
          Print version

ARGS:
  [BOOK]  File containing the book configuration file, or a Markdown file when called with --single
"""
HELP_HINT = "For more information, try '--help'."
RUNTIME_HELP_HINT = "For more information try --help."
HTML_DIR_ERROR_DETAIL = """Error compiling template: render error

  --> <anonymous>:8:7
   |
 8 |     {{favicon}}
   |       ^^^^^^^
   |
   = reason: not found in this scope"""
PDF_ERROR = "Error during temporary files editing: failed to run command 'xelatex'"
EPUB_ZIP_WARNING = "Could not run zip command, falling back to zip library"
VALID_TO = ["epub", "pdf", "html", "tex", "odt", "html.dir"]

SCRIPT_PATH = Path(__file__).resolve()
ROOT = SCRIPT_PATH.parent.parent if SCRIPT_PATH.parent.name == "src" else SCRIPT_PATH.parent
OBSERVED = ROOT / "observed"
LINK_RE = re.compile(r"\[([^\]]+)\]\(([^)]+)\)")
HEADING_RE = re.compile(r"^(#+)\s+(.*)$")
STAT_HEADING_RE = re.compile(r"(?m)^#+\s*")


class ParseError(Exception):
    def __init__(self, message: str, usage: str | None = None) -> None:
        super().__init__(message)
        self.message = message
        self.usage = usage


@dataclass
class Cli:
    force_emoji: bool = False
    single: bool = False
    no_fancy: bool = False
    verbose: bool = False
    autograph: bool = False
    quiet: bool = False
    create: list[str] | None = None
    output: str | None = None
    to: str | None = None
    set_values: list[str] | None = None
    list_options: bool = False
    runtime_lang: str | None = None
    print_template: str | None = None
    stats: bool = False
    book: str | None = None


@dataclass
class ChapterSource:
    original: str
    resolved: Path
    line_number: int | None = None
    inline_content: str | None = None


@dataclass
class Book:
    source_arg: str
    source_path: Path
    source_dir: Path
    single_mode: bool
    options: dict[str, str]
    chapters: list[ChapterSource]

    def option(self, key: str, default: str | None = None) -> str | None:
        return self.options.get(key, default)

    @property
    def lang(self) -> str:
        return self.option("lang", "en") or "en"

    @property
    def title(self) -> str:
        return self.option("title", "") or ""

    @property
    def author(self) -> str:
        return self.option("author", "") or ""

    @property
    def subtitle(self) -> str | None:
        value = self.option("subtitle")
        return value if value else None

    @property
    def autograph_text(self) -> str | None:
        value = self.option("autograph")
        return value if value else None

    @property
    def epub_version(self) -> int:
        try:
            return int(self.option("epub.version", "2") or "2")
        except ValueError:
            return 2

    def get_bool(self, key: str, default: bool) -> bool:
        value = self.option(key)
        if value is None:
            return default
        return value.strip() in {"true", "on", "yes", "1"}

    def output_path(self, format_name: str) -> str | None:
        key = {
            "html": "output.html",
            "html.dir": "output.html.dir",
            "epub": "output.epub",
            "pdf": "output.pdf",
            "tex": "output.tex",
            "odt": "output.odt",
        }[format_name]
        return self.option(key)

    def output_list(self) -> list[str]:
        raw = self.option("output")
        if not raw:
            return []
        inner = raw.strip()
        if inner.startswith("[") and inner.endswith("]"):
            inner = inner[1:-1]
        parts = re.split(r"[\s,]+", inner)
        return [part for part in parts if part]

    def default_output_name(self, format_name: str) -> str:
        stem = self.source_path.stem or "book"
        if format_name == "html":
            return f"{stem}.html"
        if format_name == "epub":
            return f"{stem}.epub"
        if format_name == "pdf":
            return f"{stem}.pdf"
        if format_name == "tex":
            return f"{stem}.tex"
        if format_name == "html.dir":
            return stem
        return f"{stem}.odt"

    @property
    def tex_class(self) -> str:
        return self.option("tex.class", "article" if self.single_mode else "book") or (
            "article" if self.single_mode else "book"
        )

    @property
    def tex_paper_size(self) -> str:
        return self.option("tex.paper.size", "a5paper") or "a5paper"

    @property
    def tex_margin_top(self) -> str:
        return self.option("tex.margin.top", "2cm") or "2cm"

    @property
    def tex_margin_bottom(self) -> str:
        return self.option("tex.margin.bottom", "1.5cm") or "1.5cm"

    @property
    def tex_margin_left(self) -> str:
        value = self.option("tex.margin.left")
        if value:
            return value
        return "2.5cm" if self.tex_class == "book" else "2cm"

    @property
    def tex_margin_right(self) -> str:
        value = self.option("tex.margin.right")
        if value:
            return value
        return "1.5cm" if self.tex_class == "book" else "2cm"


@dataclass
class Target:
    format_name: str
    destination: str | None
    explicit: bool


@dataclass
class Issue:
    severity: str
    short: str
    detailed: str | None = None


@dataclass
class Success:
    label: str
    path: str


@dataclass
class RenderedChapter:
    title: str
    title_label: str
    html_content: str
    tex_content: str


def main(argv: list[str]) -> int:
    try:
        cli = parse_cli(argv)
    except ParseError as error:
        emit_parse_error(error)
        return 2

    ui = (
        "quiet"
        if cli.quiet
        else "verbose"
        if cli.verbose
        else "nofancy"
        if cli.no_fancy
        else "default"
    )

    if cli.list_options:
        emit_banner(ui)
        sys.stdout.write(read_list_options())
        return 0

    if cli.print_template is not None:
        emit_banner(ui)
        content = read_template(cli.print_template)
        if content is None:
            emit_plain_error(ui, f"{cli.print_template} is not a valid template name")
        else:
            sys.stdout.write(content)
        return 0

    if cli.create is not None:
        emit_banner(ui)
        sys.stdout.write(render_create_output(cli.create))
        return 0

    if cli.book is None:
        emit_banner(ui)
        emit_missing_book(ui)
        return 0

    if cli.single:
        book, error = load_single_book(cli.book)
    else:
        book, error = load_config_book(cli.book)
    if error:
        emit_banner(ui)
        emit_plain_error(ui, error)
        return 0
    assert book is not None

    apply_cli_sets(book, cli.set_values or [])

    if cli.stats:
        emit_banner(ui)
        stats, error = render_stats(book)
        if error:
            emit_plain_error(ui, error)
        else:
            sys.stdout.write(stats)
        return 0

    targets = determine_targets(book, cli)
    if not targets:
        emit_banner(ui)
        return 0

    if cli.to == "odt":
        emit_banner(ui)
        emit_plain_error(ui, "unknown format odt")
        return 0

    if len(targets) == 1 and targets[0].format_name == "html.dir" and targets[0].explicit:
        emit_banner(ui)
        emit_generation_result(
            ui,
            [Issue("error", HTML_DIR_ERROR_DETAIL.splitlines()[0], HTML_DIR_ERROR_DETAIL)],
            [],
        )
        return 0

    chapters, error = render_chapters(book)
    if error:
        emit_banner(ui)
        emit_plain_error(ui, error)
        return 0
    assert chapters is not None

    emit_banner(ui)
    issues, successes = generate_outputs(ui, book, chapters, targets)
    emit_generation_result(ui, issues, successes)
    return 0


def parse_cli(argv: list[str]) -> Cli:
    cli = Cli(set_values=[])
    positional: list[str] = []
    i = 0
    parsing_options = True

    while i < len(argv):
        token = argv[i]
        if parsing_options and token == "--":
            parsing_options = False
            i += 1
            continue

        if parsing_options and token in {"-h", "--help"}:
            sys.stdout.write(HELP_TEXT)
            raise SystemExit(0)
        if parsing_options and token in {"-V", "--version"}:
            sys.stdout.write(f"{VERSION}\n")
            raise SystemExit(0)

        if parsing_options and token in {"-f", "--force-emoji"}:
            cli.force_emoji = True
            i += 1
            continue
        if parsing_options and token in {"-s", "--single"}:
            cli.single = True
            i += 1
            continue
        if parsing_options and token in {"-n", "--no-fancy"}:
            cli.no_fancy = True
            i += 1
            continue
        if parsing_options and token in {"-v", "--verbose"}:
            cli.verbose = True
            i += 1
            continue
        if parsing_options and token in {"-a", "--autograph"}:
            cli.autograph = True
            i += 1
            continue
        if parsing_options and token in {"-q", "--quiet"}:
            cli.quiet = True
            i += 1
            continue
        if parsing_options and token in {"-l", "--list-options"}:
            cli.list_options = True
            i += 1
            continue
        if parsing_options and token in {"-S", "--stats"}:
            cli.stats = True
            i += 1
            continue

        if parsing_options and token in {"-o", "--output"}:
            if i + 1 >= len(argv):
                raise ParseError("a value is required for '--output <output>' but none was supplied")
            cli.output = argv[i + 1]
            i += 2
            continue
        if parsing_options and token.startswith("--output="):
            cli.output = token.split("=", 1)[1]
            i += 1
            continue

        if parsing_options and token in {"-t", "--to"}:
            if i + 1 >= len(argv):
                raise ParseError("a value is required for '--to <to>' but none was supplied")
            value = argv[i + 1]
            if value not in VALID_TO:
                raise ParseError(
                    f"invalid value '{value}' for '--to <to>'\n  [possible values: {', '.join(VALID_TO)}]"
                )
            cli.to = value
            i += 2
            continue
        if parsing_options and token.startswith("--to="):
            value = token.split("=", 1)[1]
            if value not in VALID_TO:
                raise ParseError(
                    f"invalid value '{value}' for '--to <to>'\n  [possible values: {', '.join(VALID_TO)}]"
                )
            cli.to = value
            i += 1
            continue

        if parsing_options and token in {"-L", "--lang"}:
            if i + 1 >= len(argv):
                raise ParseError("a value is required for '--lang <lang>' but none was supplied")
            cli.runtime_lang = argv[i + 1]
            i += 2
            continue
        if parsing_options and token.startswith("--lang="):
            cli.runtime_lang = token.split("=", 1)[1]
            i += 1
            continue

        if parsing_options and token == "--print-template":
            if i + 1 >= len(argv):
                raise ParseError(
                    "a value is required for '--print-template <print-template>' but none was supplied"
                )
            cli.print_template = argv[i + 1]
            i += 2
            continue
        if parsing_options and token.startswith("--print-template="):
            cli.print_template = token.split("=", 1)[1]
            i += 1
            continue

        if parsing_options and token in {"-c", "--create"}:
            values, next_index = consume_variadic(argv, i + 1)
            if not values:
                raise ParseError("a value is required for '--create <files>...' but none was supplied")
            cli.create = values
            i = next_index
            continue

        if parsing_options and token == "--set":
            values, next_index = consume_variadic(argv, i + 1)
            if len(values) < 2:
                provided = len(values)
                noun = "value was" if provided == 1 else "values were"
                raise ParseError(
                    f"2 values required by '--set <set> <set>...'; only {provided} {noun} provided",
                    "executable [OPTIONS] [BOOK]",
                )
            cli.set_values.extend(values)
            i = next_index
            continue

        if parsing_options and token.startswith("-") and token != "-":
            raise ParseError(f"Found argument '{token}' which wasn't expected")

        positional.append(token)
        i += 1

    if cli.output is not None and cli.to is None:
        usage = (
            "executable --to <to> --create <files>... --output <output> [BOOK]"
            if cli.create is not None
            else "executable --to <to> --output <output> <BOOK>"
        )
        raise ParseError("the following required arguments were not provided:\n  --to <to>", usage)

    if len(positional) > 1:
        raise ParseError("Found argument '{}' which wasn't expected".format(positional[1]))
    cli.book = positional[0] if positional else None
    return cli


def consume_variadic(argv: list[str], start: int) -> tuple[list[str], int]:
    values: list[str] = []
    i = start
    while i < len(argv):
        token = argv[i]
        if token == "--":
            break
        if token.startswith("-") and token != "-":
            break
        values.append(token)
        i += 1
    return values, i


def emit_parse_error(error: ParseError) -> None:
    sys.stderr.write(f"error: {error.message}\n\n")
    if error.usage:
        sys.stderr.write(f"Usage: {error.usage}\n\n")
    sys.stderr.write(f"{HELP_HINT}\n")


def emit_banner(ui: str) -> None:
    if ui != "quiet":
        sys.stderr.write(f"{BANNER}\n")


def emit_plain_error(ui: str, message: str) -> None:
    del ui
    sys.stderr.write(f"ERROR {message}\n")


def emit_missing_book(ui: str) -> None:
    del ui
    sys.stderr.write("ERROR You must pass the name of a book configuration file.\n")
    sys.stderr.write(f"{RUNTIME_HELP_HINT}\n")


def emit_generation_result(ui: str, issues: list[Issue], successes: list[Success]) -> None:
    if ui == "default":
        if any(issue.severity == "warn" for issue in issues):
            sys.stderr.write("WARNING Crowbook exited successfully, but the following errors occurred:\n")
            for issue in issues:
                label = "WARNING" if issue.severity == "warn" else "ERROR"
                sys.stderr.write(f"{label} {issue.short}\n")
            return
        for issue in issues:
            if issue.detailed:
                sys.stderr.write(f"ERROR {issue.detailed}\n")
            else:
                sys.stderr.write(f"ERROR {issue.short}\n")
        return

    if ui == "quiet":
        for issue in issues:
            if issue.severity == "error":
                detail = issue.detailed if issue.detailed else issue.short
                sys.stderr.write(f"[ERROR] {detail}\n")
        return

    if ui == "verbose":
        sys.stderr.write("07:04:02 [DEBUG] (1) crowbook::book: Ignoring YAML block:\n\n")

    for issue in issues:
        label = "[WARN]" if issue.severity == "warn" else "[ERROR]"
        detail = issue.detailed if issue.detailed else issue.short
        sys.stderr.write(f"{label} {detail}\n")
    for success in successes:
        sys.stderr.write(f"[INFO] Succesfully generated {success.label}: {success.path}\n")


def read_list_options() -> str:
    return (OBSERVED / "misc" / "list-options.txt").read_text(encoding="utf-8")


def read_template(name: str) -> str | None:
    mapping = {
        "html.css": OBSERVED / "templates" / "html.css",
        "html.css.colors": OBSERVED / "templates" / "html.css.colors",
        "html.js": OBSERVED / "templates" / "html.js",
        "html.css.print": OBSERVED / "templates" / "html.css.print",
        "html.standalone.template": OBSERVED / "templates" / "html.standalone.template",
        "html.standalone.js": OBSERVED / "templates" / "html.standalone.js",
        "html.dir.template": OBSERVED / "templates" / "html.dir.template",
        "epub.css": OBSERVED / "templates" / "epub.css",
        "epub.chapter.xhtml": OBSERVED / "templates" / "epub.chapter.xhtml",
        "epub.titlepage.xhtml": OBSERVED / "templates" / "epub.titlepage.xhtml",
        "tex.template": OBSERVED / "templates" / "tex.template",
        "html.highlight.css": OBSERVED / "templates" / "html.highlight.css",
        "html.highlight.js": OBSERVED / "templates" / "html.highlight.js",
    }
    path = mapping.get(name)
    return path.read_text(encoding="utf-8") if path else None


def render_create_output(files: list[str]) -> str:
    lines = [
        '"author: Your name"',
        '"title: Your title"',
        '"lang: en"',
        "",
        '"## Output formats"',
        "",
        '"# Uncomment and fill to generate files"',
        '"# output.html: some_file.html"',
        '"# output.epub: some_file.epub"',
        '"# output.pdf: some_file.pdf"',
        "",
        '"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file\'s name"',
        '"# output: [pdf, epub, html]"',
        "",
        '"# Uncomment and fill to set cover image (for EPUB)"',
        '"# cover: some_cover.png"',
        "",
        "## List of chapters",
    ]
    lines.extend(f"+ {file}" for file in files)
    return "\n".join(lines) + "\n"


def load_config_book(book_arg: str) -> tuple[Book | None, str | None]:
    source_path = Path(book_arg)
    try:
        content = source_path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return None, f"Could not find file '{book_arg}' for book"

    options: dict[str, str] = {}
    chapters: list[ChapterSource] = []
    source_dir = source_path.parent if source_path.parent != Path("") else Path(".")
    for line_number, line in enumerate(content.splitlines(), start=1):
        trimmed = line.strip()
        if not trimmed or trimmed.startswith("#"):
            continue
        if trimmed.startswith("+ "):
            original = trimmed[2:].strip()
            chapters.append(
                ChapterSource(
                    original=original,
                    resolved=source_dir / original,
                    line_number=line_number,
                )
            )
            continue
        if ":" in line:
            key, value = line.split(":", 1)
            options[key.strip()] = value.strip()

    return (
        Book(
            source_arg=book_arg,
            source_path=source_path,
            source_dir=source_dir,
            single_mode=False,
            options=options,
            chapters=chapters,
        ),
        None,
    )


def load_single_book(book_arg: str) -> tuple[Book | None, str | None]:
    source_path = Path(book_arg)
    try:
        content = source_path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return None, f"{book_arg}: Could not find file '{book_arg}' for book chapter"

    options, body = split_front_matter(content)
    source_dir = source_path.parent if source_path.parent != Path("") else Path(".")
    chapters = [ChapterSource(original=book_arg, resolved=source_path, inline_content=body)]
    return (
        Book(
            source_arg=book_arg,
            source_path=source_path,
            source_dir=source_dir,
            single_mode=True,
            options=options,
            chapters=chapters,
        ),
        None,
    )


def split_front_matter(content: str) -> tuple[dict[str, str], str]:
    normalized = content.replace("\r\n", "\n")
    if not normalized.startswith("---\n"):
        return {}, normalized
    parts = normalized.split("\n---\n", 2)
    if len(parts) < 3:
        return {}, normalized
    _, front_matter, body = parts
    options: dict[str, str] = {}
    for line in front_matter.splitlines():
        if ":" in line:
            key, value = line.split(":", 1)
            options[key.strip()] = value.strip()
    return options, body


def apply_cli_sets(book: Book, values: list[str]) -> None:
    for index in range(0, len(values), 2):
        if index + 1 < len(values):
            book.options[values[index]] = values[index + 1]


def render_stats(book: Book) -> tuple[str | None, str | None]:
    rows: list[tuple[str, int, int]] = []
    total_chars = 0
    total_words = 0

    for chapter in book.chapters:
        raw, error = load_raw_chapter(book, chapter)
        if error:
            return None, error
        stripped = strip_markdown_for_stats(raw)
        chars = len(stripped)
        words = len(stripped.split())
        total_chars += chars
        total_words += words
        rows.append((chapter.original, chars, words))

    lines = ["Chapter      Chars      Words  Chars/Word", "---------"]
    for name, chars, words in rows:
        ratio = 0.0 if words == 0 else chars / words
        lines.append(f"{name:<11}{chars:>10}{words:>11}{ratio:>12.2f}")
    total_ratio = 0.0 if total_words == 0 else total_chars / total_words
    lines.append("---------")
    lines.append(f"TOTAL:{total_chars:>12}{total_words:>11}{total_ratio:>12.2f}")
    lines.append("")
    return "\n".join(lines), None


def strip_markdown_for_stats(raw: str) -> str:
    stripped = LINK_RE.sub(r"\1", raw)
    stripped = STAT_HEADING_RE.sub("", stripped)
    return stripped.replace("\n", "")


def load_raw_chapter(book: Book, chapter: ChapterSource) -> tuple[str, str | None]:
    if chapter.inline_content is not None:
        return chapter.inline_content, None
    try:
        return chapter.resolved.read_text(encoding="utf-8"), None
    except FileNotFoundError:
        if chapter.line_number is not None:
            return "", f"{book.source_arg}:{chapter.line_number}: Could not find file '{chapter.resolved}' for book chapter"
        return "", f"{chapter.original}: Could not find file '{chapter.original}' for book chapter"


def render_chapters(book: Book) -> tuple[list[RenderedChapter] | None, str | None]:
    rendered: list[RenderedChapter] = []
    paragraph_index = 1
    smart_quotes = book.get_bool("input.clean.smart_quotes", True)
    ligature_dashes = book.get_bool("input.clean.ligature.dashes", False)
    ligature_guillemets = book.get_bool("input.clean.ligature.guillemets", False)

    for chapter_number, chapter in enumerate(book.chapters, start=1):
        raw, error = load_raw_chapter(book, chapter)
        if error:
            return None, error
        cleaned = clean_markdown(
            raw,
            book.lang,
            smart_quotes=smart_quotes,
            ligature_dashes=ligature_dashes,
            ligature_guillemets=ligature_guillemets,
        )
        blocks = parse_blocks(cleaned)
        if blocks and blocks[0][0] == "heading" and blocks[0][1] == 1:
            title = blocks[0][2]
            blocks = blocks[1:]
        else:
            title = chapter.resolved.stem or "Chapter"
        html_content = render_chapter_html(title, blocks, chapter_number, book.lang, paragraph_index)
        paragraph_index += sum(1 for block in blocks if block[0] == "paragraph")
        tex_content = render_chapter_tex(title, blocks, chapter_number - 1)
        rendered.append(
            RenderedChapter(
                title=title,
                title_label=f"{chapter_number}. {title}",
                html_content=html_content,
                tex_content=tex_content,
            )
        )
    return rendered, None


def clean_markdown(
    raw: str,
    lang: str,
    *,
    smart_quotes: bool,
    ligature_dashes: bool,
    ligature_guillemets: bool,
) -> str:
    text = raw.replace("\r\n", "\n")
    if ligature_dashes:
        text = text.replace("---", "—").replace("--", "–")
    if ligature_guillemets:
        text = text.replace("<<", "«").replace(">>", "»")
    if smart_quotes:
        text = convert_double_quotes(text)
    if lang == "fr":
        return text
    return text


def convert_double_quotes(text: str) -> str:
    pieces: list[str] = []
    opening = True
    for char in text:
        if char == '"':
            pieces.append("“" if opening else "”")
            opening = not opening
        else:
            pieces.append(char)
    return "".join(pieces)


def parse_blocks(markdown: str) -> list[tuple[str, int, str]]:
    blocks: list[tuple[str, int, str]] = []
    paragraph_lines: list[str] = []

    def flush_paragraph() -> None:
        if paragraph_lines:
            blocks.append(("paragraph", 0, " ".join(paragraph_lines)))
            paragraph_lines.clear()

    for line in markdown.splitlines():
        trimmed = line.strip()
        if not trimmed:
            flush_paragraph()
            continue
        match = HEADING_RE.match(trimmed)
        if match:
            flush_paragraph()
            blocks.append(("heading", len(match.group(1)), match.group(2)))
        else:
            paragraph_lines.append(trimmed)
    flush_paragraph()
    return blocks


def render_chapter_html(
    title: str,
    blocks: list[tuple[str, int, str]],
    chapter_number: int,
    lang: str,
    paragraph_index: int,
) -> str:
    lines = [
        f"  <h1 id = 'link-{chapter_number}'><span class = 'chapter-header'>{chapter_word(lang)} {chapter_number}</span><br />{escape_html(title)}</h1>"
    ]
    current_paragraph = paragraph_index
    for kind, level, text in blocks:
        if kind == "paragraph":
            lines.append(f'<p id = "para-{current_paragraph}">{render_inline_html(text, lang)}</p>')
            current_paragraph += 1
        elif kind == "heading":
            heading_level = min(level + 1, 6)
            lines.append(f"<h{heading_level}>{escape_html(text)}</h{heading_level}>")
    return "\n".join(lines)


def render_chapter_tex(title: str, blocks: list[tuple[str, int, str]], chapter_index: int) -> str:
    lines = [f"\\chapter{{{escape_tex(title)}}}", f"\\label{{chapter-{chapter_index}}}"]
    for kind, level, text in blocks:
        if kind == "paragraph":
            lines.append(render_inline_tex(text))
            lines.append("")
        elif kind == "heading":
            command = {1: "\\section", 2: "\\subsection", 3: "\\subsubsection"}.get(level, "\\paragraph")
            lines.append(f"{command}{{{escape_tex(text)}}}")
            lines.append("")
    return "\n".join(lines).rstrip()


def render_inline_html(text: str, lang: str) -> str:
    pieces: list[str] = []
    last = 0
    for match in LINK_RE.finditer(text):
        pieces.append(render_html_text(text[last : match.start()], lang))
        label = render_html_text(match.group(1), lang)
        href = escape_html_attribute(match.group(2))
        pieces.append(f'<a href = "{href}">{label}</a>')
        last = match.end()
    pieces.append(render_html_text(text[last:], lang))
    return "".join(pieces)


def render_inline_tex(text: str) -> str:
    pieces: list[str] = []
    last = 0
    for match in LINK_RE.finditer(text):
        pieces.append(escape_tex(text[last : match.start()]))
        label = escape_tex(match.group(1))
        href = escape_tex(match.group(2))
        pieces.append(f"\\href{{{href}}}{{{label}}}\\protect\\footnote{{\\url{{{href}}}}}")
        last = match.end()
    pieces.append(escape_tex(text[last:]))
    return "".join(pieces)


def render_html_text(text: str, lang: str) -> str:
    escaped = escape_html(text)
    if lang != "fr":
        return escaped
    escaped = escaped.replace(" :", "\u00a0:")
    escaped = escaped.replace(" ;", "&#160;;")
    escaped = escaped.replace(" ?", "&#160;?")
    escaped = escaped.replace(" !", "&#160;!")
    escaped = escaped.replace("« ", "«&#160;")
    escaped = escaped.replace(" »", "&#160;»")
    tokens = escaped.split(" ")
    output_tokens: list[str] = []
    for token in tokens:
        if "&#160;" in token:
            output_tokens.append(f'<span class = "nnbsp">{token}</span>')
        else:
            output_tokens.append(token)
    return " ".join(output_tokens)


def escape_html(text: str) -> str:
    return html.escape(text, quote=False)


def escape_html_attribute(text: str) -> str:
    return html.escape(text, quote=True)


def escape_tex(text: str) -> str:
    pieces: list[str] = []
    i = 0
    while i < len(text):
        if text.startswith("--", i):
            pieces.append("-{}-")
            i += 2
            continue
        char = text[i]
        mapping = {
            "\\": "\\textbackslash{}",
            "{": "\\{",
            "}": "\\}",
            "$": "\\$",
            "&": "\\&",
            "%": "\\%",
            "#": "\\#",
            "_": "\\_",
            "^": "\\^{}",
            "~": "\\~{}",
            "<": "\\textless{}",
            ">": "\\textgreater{}",
        }
        pieces.append(mapping.get(char, char))
        i += 1
    return "".join(pieces)


def determine_targets(book: Book, cli: Cli) -> list[Target]:
    if cli.to is not None:
        if cli.output is not None:
            destination = cli.output
        else:
            destination = book.output_path(cli.to)
            if destination is None:
                if cli.to in {"html", "tex", "epub"}:
                    destination = None
                else:
                    destination = book.default_output_name(cli.to)
            elif destination == "-":
                destination = None
        return [Target(cli.to, destination, True)]

    targets: list[Target] = []
    seen: set[str] = set()
    for format_name in ["html.dir", "html", "pdf", "epub", "tex"]:
        destination = book.output_path(format_name)
        if destination:
            targets.append(Target(format_name, None if destination == "-" else destination, False))
            seen.add(format_name)

    for format_name in book.output_list():
        if format_name == "odt" or format_name not in VALID_TO or format_name in seen:
            continue
        targets.append(Target(format_name, book.default_output_name(format_name), False))
        seen.add(format_name)
    return targets


def generate_outputs(
    ui: str,
    book: Book,
    chapters: list[RenderedChapter],
    targets: list[Target],
) -> tuple[list[Issue], list[Success]]:
    del ui
    issues: list[Issue] = []
    successes: list[Success] = []
    ordered = sorted(targets, key=lambda target: {"epub": 0, "html.dir": 1, "html": 2, "pdf": 3, "tex": 4}.get(target.format_name, 99))

    for target in ordered:
        if target.format_name == "html":
            content = render_standalone_html(book, chapters)
            write_text_output(target.destination, content)
            if target.destination:
                successes.append(Success("HTML (standalone page)", target.destination))
        elif target.format_name == "epub":
            if shutil.which(book.option("crowbook.zip.command", "zip") or "zip") is None:
                issues.append(Issue("warn", EPUB_ZIP_WARNING))
            write_epub(book, chapters, target.destination)
            if target.destination:
                successes.append(Success("EPUB", target.destination))
        elif target.format_name == "pdf":
            short = PDF_ERROR if target.explicit else f"Error rendering pdf: {PDF_ERROR}"
            issues.append(Issue("error", short))
        elif target.format_name == "tex":
            content = render_tex(book, chapters)
            write_text_output(target.destination, content)
        elif target.format_name == "html.dir":
            if not target.explicit and target.destination:
                write_html_dir(book, chapters, target.destination)
                issues.append(
                    Issue(
                        "error",
                        "Error rendering html.dir: Error compiling template: render error",
                        f"Error rendering html.dir: {HTML_DIR_ERROR_DETAIL}",
                    )
                )

    return issues, successes


def write_text_output(destination: str | None, content: str) -> None:
    if destination is None:
        sys.stdout.write(content)
        return
    path = Path(destination)
    if path.parent != Path("") and not path.parent.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")


def render_standalone_html(book: Book, chapters: list[RenderedChapter]) -> str:
    lang = book.lang
    title = escape_html(book.title)
    author = escape_html(book.author)
    subtitle = escape_html(book.subtitle) if book.subtitle else None
    autograph = escape_html(book.autograph_text) if book.autograph_text else None
    style = render_html_css(lang)
    print_style = read_template("html.css.print") or ""
    script = read_template("html.js") or ""
    json_data = render_json_ld(book)
    has_toc = len(chapters) > 1
    toc = render_standalone_toc(chapters) if has_toc else ""
    chapter_blocks = []
    for index, chapter in enumerate(chapters):
        chapter_blocks.append(f'<div id = "chapter-{index}" class = "chapter">\n{chapter.html_content}\n\n</div>')
    content = "\n".join(chapter_blocks)

    lines = [
        "<!DOCTYPE html>",
        f'<html lang="{lang}">',
        "  <head>",
        '    <meta charset="utf-8">',
        '    <meta name="generator" content="crowbook">',
        '    <meta name="viewport" content="width=device-width">',
        f'    <meta name="author" content="{author}">',
        "    ",
        f"    <title>{title}</title>",
        '    <style type = "text/css">',
        f"      {style}",
        "    </style>",
        '    <style type = "text/css" media = "print">',
        f"      {print_style}",
        "    </style>",
        "    ",
        "   <script>",
        f"    {script}",
        "   </script>",
        "",
        "",
        "  </head>",
        "  <body>",
        f"    {json_data}",
    ]
    if has_toc:
        lines.extend(
            [
                '    <nav id = "nav">',
                '      <div id = "nav-title">',
                f'        <h2><a href = "#link-0">{title}</a></h2>',
                "      </div>",
                f"      {toc}",
                "    </nav>",
            ]
        )
    lines.extend(
        [
            "",
            '    <div id = "content">',
            "      ",
            '      <div id = "page">',
            "        <header>",
            "",
            '          <div id = "menu">',
        ]
    )
    if has_toc:
        lines.extend(
            [
                '            <img id = "menu-button" onclick="toggle();"'
                ,
                '                 src="menu.svg"',
                f'                 alt = "{toc_title(lang)}" title = "{toc_title(lang)}" />',
            ]
        )
    else:
        lines.append("\t        ")
    lines.extend(
        [
            "          </div>",
            f'\t  <h2 class="author">{author}</h2>',
            f'          <h1 id = "link-0" class="title" >{title}</h1>',
        ]
    )
    if subtitle:
        lines.append(f'\t  <h2 class = "subtitle">{subtitle}</h2>')
    else:
        lines.append("\t  ")
    if autograph:
        lines.extend(["\t  <div id = \"autograph\">", f"\t    {autograph}", "\t  </div>"])
    else:
        lines.append("\t  ")
    lines.extend(
        [
            "        </header>",
            "",
            f"        {content}",
            "",
            "      </div>",
            "      ",
            "    </div>",
            "  </body>",
            "</html>",
            "",
        ]
    )
    return "\n".join(lines)


def render_standalone_toc(chapters: list[RenderedChapter]) -> str:
    lines = ["<ul>"]
    for index, chapter in enumerate(chapters, start=1):
        lines.append(f'      <li><a href="#link-{index}">{escape_html(chapter.title_label)}</a></li>')
    lines.append("    </ul>")
    return "\n".join(lines)


def render_html_css(lang: str) -> str:
    css = read_template("html.css") or ""
    fr_block = """{% if lang | eq: "fr" %}
/* Make list displays '–' instead of bullets */
ul li {
    list-style-type: '–';
    padding-left: .5em;
}
{% endif %}
"""
    replacement = (
        "/* Make list displays '–' instead of bullets */\nul li {\n    list-style-type: '–';\n    padding-left: .5em;\n}\n"
        if lang == "fr"
        else ""
    )
    css = css.replace(fr_block, replacement)
    css = css.replace("{{additional_code}}", "")
    css = css.replace("{{colors}}", read_template("html.css.colors") or "")
    return css


def render_epub_css(lang: str) -> str:
    css = read_template("epub.css") or ""
    fr_block = """{% if lang | eq: "fr" %}
/* Make list displays '–' instead of bullets */
ul li {
    list-style-type: '–';
    padding-left: .5em;
}
{% endif %}
"""
    replacement = (
        "/* Make list displays '–' instead of bullets */\nul li {\n    list-style-type: '–';\n    padding-left: .5em;\n}\n"
        if lang == "fr"
        else ""
    )
    css = css.replace(fr_block, replacement)
    css = css.replace("{{additional_code}}", "")
    return css


def render_json_ld(book: Book) -> str:
    return (
        "<script type = 'application/ld+json'>\n{\n"
        f'    "@context": "http://schema.org/",\n'
        f'    "@type": "Book",\n'
        f'    "author": "{escape_html(book.author)}",\n'
        f'    "name": "{escape_html(book.title)}",\n'
        "    \n    \n    \n    \n    \n"
        f'    "inLanguage": "{book.lang}"\n'
        "}\n</script>"
    )


def write_epub(book: Book, chapters: list[RenderedChapter], destination: str | None) -> None:
    if destination is None:
        out = sys.stdout.buffer
        zf = zipfile.ZipFile(out, "w")
    else:
        path = Path(destination)
        if path.parent != Path("") and not path.parent.exists():
            path.parent.mkdir(parents=True, exist_ok=True)
        zf = zipfile.ZipFile(path, "w")
    with zf:
        zf.writestr("mimetype", "application/epub+zip", compress_type=zipfile.ZIP_STORED)
        zf.writestr("META-INF/container.xml", render_container_xml(), compress_type=zipfile.ZIP_DEFLATED)
        zf.writestr(
            "META-INF/com.apple.ibooks.display-options.xml",
            render_ibooks_display_options(),
            compress_type=zipfile.ZIP_DEFLATED,
        )
        zf.writestr("OEBPS/title_page.xhtml", render_epub_title_page(book), compress_type=zipfile.ZIP_DEFLATED)
        for index, chapter in enumerate(chapters):
            zf.writestr(
                f"OEBPS/chapter_{index:03}.xhtml",
                render_epub_chapter(book, chapter),
                compress_type=zipfile.ZIP_DEFLATED,
            )
        zf.writestr("OEBPS/stylesheet.css", render_epub_css(book.lang), compress_type=zipfile.ZIP_DEFLATED)
        zf.writestr("OEBPS/content.opf", render_opf(book, chapters), compress_type=zipfile.ZIP_DEFLATED)
        zf.writestr("OEBPS/toc.ncx", render_toc_ncx(book, chapters), compress_type=zipfile.ZIP_DEFLATED)
        zf.writestr("OEBPS/nav.xhtml", render_nav_xhtml(book, chapters), compress_type=zipfile.ZIP_DEFLATED)


def render_container_xml() -> str:
    return """<?xml version="1.0" encoding="UTF-8"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
  <rootfiles>
    <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml" />
  </rootfiles>
</container>
"""


def render_ibooks_display_options() -> str:
    return """<?xml version="1.0" encoding="UTF-8"?>
<display_options>
  <platform name="*">
    <option name="specified-fonts">true</option>
  </platform>
</display_options>
"""


def render_epub_title_page(book: Book) -> str:
    title = escape_html(book.title)
    author = escape_html(book.author)
    subtitle = escape_html(book.subtitle) if book.subtitle else None
    autograph = escape_html(book.autograph_text) if book.autograph_text else None
    lines = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        '<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.1//EN" "http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd">',
        f'<html xmlns="http://www.w3.org/1999/xhtml" xml:lang="{book.lang}">',
        "<head>",
        '  <meta http-equiv="Content-Type" content="text/html; charset=utf-8" />',
        '  <meta http-equiv="Content-Style-Type" content="text/css" />',
        '  <meta name="generator" content="crowbook" />',
        f"  <title>{title}</title>",
        '  <link rel="stylesheet" type="text/css" href="stylesheet.css" />',
        "</head>",
        "<body>",
        f'  <h2 class="author">{author}</h2>',
        f'  <h1 class="title">{title}</h1>',
    ]
    if subtitle:
        lines.append(f'  <h2 class = "subtitle">{subtitle}</h2>')
    else:
        lines.append("  ")
    if autograph:
        lines.append(f'  <div id = "autograph">{autograph}</div>')
    else:
        lines.append("  ")
    lines.extend(["</body>", "</html>", ""])
    return "\n".join(lines)


def render_epub_chapter(book: Book, chapter: RenderedChapter) -> str:
    lines = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        '<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.1//EN" "http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd">',
        f'<html xmlns="http://www.w3.org/1999/xhtml" xml:lang="{book.lang}" lang="{book.lang}">',
        "  <head>",
        '  <meta http-equiv="Content-Type" content="text/html; charset=utf-8" />',
        '  <meta http-equiv="Content-Style-Type" content="text/css" />',
        '  <meta name="generator" content="crowbook" />',
        f"  <title>{escape_html(chapter.title_label)}</title>",
        '  <link rel="stylesheet" type="text/css" href="stylesheet.css" />',
        "  </head>",
        f'  <body xml:lang="{book.lang}" lang="{book.lang}">',
        '    <div id = "page">',
        chapter.html_content,
        "    </div>",
        "  </body>",
        "</html>",
        "",
    ]
    return "\n".join(lines)


def render_nav_xhtml(book: Book, chapters: list[RenderedChapter]) -> str:
    if book.epub_version == 3:
        lines = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            "<!DOCTYPE html>",
            '<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">',
            "<head>",
            '  <meta charset = "utf-8" />',
            '  <meta name="generator" content="crowbook" />',
            f"  <title>{toc_title(book.lang)}</title>",
            '  <link rel="stylesheet" type="text/css" href="stylesheet.css" />',
            "</head>",
            "<body>",
            '  <nav epub:type = "toc" id="toc">',
            f'    <h1 id="toc-title">{toc_title(book.lang)}</h1>',
            "    <ol>",
            f'      <li><a href="title_page.xhtml">{title_page_label(book.lang)}</a></li>',
        ]
        for index, chapter in enumerate(chapters):
            lines.append(f'      <li><a href="chapter_{index:03}.xhtml">{escape_html(chapter.title_label)}</a></li>')
        lines.extend(
            [
                "    </ol>",
                "  </nav>",
